const CDN={pdfLib:'https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js',pdfJs:'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.3.136/pdf.min.mjs',pdfWorker:'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.3.136/pdf.worker.min.mjs',qr:'https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js',heic:'https://cdn.jsdelivr.net/npm/heic2any@0.0.4/dist/heic2any.min.js',jsPDF:'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js',crypto:'https://cdnjs.cloudflare.com/ajax/libs/crypto-js/4.2.0/crypto-js.min.js',piexif:'https://cdn.jsdelivr.net/npm/piexifjs@1.0.6/piexif.min.js',diff:'https://cdnjs.cloudflare.com/ajax/libs/diff/5.2.0/diff.min.js',zip:'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js'};
const CATEGORIES={Image:['image-compressor','image-resizer','heic-to-jpg','webp-converter','image-to-pdf','exif-remover','exam-photo-resizer'],PDF:['pdf-compressor','pdf-merger','pdf-splitter','pdf-to-images'],Developer:['json-formatter','base64','url-encoder','hash-generator','uuid-generator','timestamp-converter','color-picker','css-minifier','regex-tester','markdown-to-html','ip-lookup'],Text:['word-counter','text-case','text-diff','lorem-ipsum','char-counter','password-strength'],Converters:['unit-converter','aspect-ratio','number-to-words'],QR:['qr-generator','whatsapp-link','upi-qr'],Calculators:['age-calculator','bmi-calculator','percentage-calculator','compound-interest','discount-calculator','tip-calculator','gst-calculator','emi-calculator','sip-calculator','income-tax-calculator','cgpa-to-percentage'],Security:['password-generator']};
const PILLS=['All','Image','PDF','Developer','Text','Converters','QR','Calculators'];
const TOOLS={};
let activeFilter='All';
const _loaded=new Set();
function injectScript(url){return new Promise((res,rej)=>{if(_loaded.has(url)){res();return;}const s=document.createElement('script');s.src=url;s.onload=()=>{_loaded.add(url);res();};s.onerror=()=>rej(new Error(`Failed to load ${url}`));document.head.appendChild(s);});}
let _pdfjs=null;async function loadPdfJs(){if(_pdfjs)return _pdfjs;_pdfjs=await import(CDN.pdfJs);_pdfjs.GlobalWorkerOptions.workerSrc=CDN.pdfWorker;return _pdfjs;}
function debounce(fn,ms){let t;return(...args)=>{clearTimeout(t);t=setTimeout(()=>fn(...args),ms);};}
function $(sel,root=document){return root.querySelector(sel)}function $$(sel,root=document){return Array.from(root.querySelectorAll(sel))}
function escapeHtml(s){return String(s??'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));}
function fileSize(bytes){if(!Number.isFinite(bytes))return '0 B';const u=['B','KB','MB','GB'];let i=0,n=bytes;while(n>=1024&&i<u.length-1){n/=1024;i++;}return `${n.toFixed(n<10&&i?1:0)} ${u[i]}`;}
function rupee(n){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0)}
function num(n,d=2){return Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:d})}
function download(blob,filename){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function copyText(text){navigator.clipboard.writeText(String(text||'')).then(()=>toast('Copied','success')).catch(()=>toast('Copy failed','error'));}
function toast(msg,type='default',duration=3000){const t=document.createElement('div');t.className=`toast ${type}`;t.textContent=msg;document.getElementById('toast-container').appendChild(t);setTimeout(()=>t.remove(),duration);}
function showError(container,msg){container.insertAdjacentHTML('beforeend',`<div class="error-state"><i class="ti ti-alert-circle" aria-hidden="true" style="font-size:16px;flex-shrink:0;margin-top:1px"></i><span>${escapeHtml(msg)}</span></div>`);}
function showLoading(container){container.innerHTML='<div class="loading"><div class="spinner"></div>Loading tool...</div>';}
function clearNode(n){while(n.firstChild)n.removeChild(n.firstChild)}
function privacy(){return '<div class="privacy-note"><i class="ti ti-lock" aria-hidden="true"></i>Files never leave your device — all processing runs in your browser</div>'}
