function makeDropZone(accept,onFiles,multiple=true,title='Drop files here',sub=null){const dz=document.createElement('div');dz.className='drop-zone';dz.innerHTML=`<i class="ti ti-upload drop-zone-icon" aria-hidden="true"></i><div class="drop-zone-title">${escapeHtml(title)}</div><div class="drop-zone-sub">${escapeHtml(sub||accept+' — up to 50 MB each')}</div><label class="drop-zone-btn"><i class="ti ti-folder-open" aria-hidden="true" style="font-size:14px"></i>Browse files<input type="file" hidden accept="${accept}" ${multiple?'multiple':''}></label>`;['dragenter','dragover','dragleave','drop'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();e.stopPropagation();}));['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,()=>dz.classList.add('drag-over')));['dragleave','drop'].forEach(ev=>dz.addEventListener(ev,()=>dz.classList.remove('drag-over')));dz.addEventListener('drop',e=>onFiles(e.dataTransfer.files));$('input',dz).addEventListener('change',e=>onFiles(e.target.files));return dz;}
function pillGroup(values,current,onChange){const wrap=document.createElement('div');wrap.className='pill-group';values.forEach(v=>{const b=document.createElement('button');b.type='button';b.className='pill-opt'+(v===current?' active':'');b.textContent=v;b.addEventListener('click',()=>{$$('.pill-opt',wrap).forEach(x=>x.classList.remove('active'));b.classList.add('active');onChange(v);});wrap.appendChild(b);});return wrap;}
function statGrid(stats){return `<div class="calc-result"><div class="calc-result-grid">${stats.map(s=>`<div class="calc-stat"><div class="calc-stat-label">${escapeHtml(s.label)}</div><div class="calc-stat-value ${s.cls||''}">${s.value}</div></div>`).join('')}</div></div>`}
function resultBox(title,content){return `<div class="calc-result"><div class="calc-stat-label">${escapeHtml(title)}</div><div class="calc-stat-value">${content}</div></div>`}
function rowsContainer(title='Results',summary=''){const box=document.createElement('div');box.className='results';box.innerHTML=`<div class="results-header"><div class="results-title">${escapeHtml(title)}</div><div class="results-summary">${escapeHtml(summary)}</div></div><div class="result-rows"></div>`;return box;}
function addResultRow(rows,{name,oldSize,newSize,pct,blob,filename,extra}){const r=document.createElement('div');r.className='result-row';r.innerHTML=`<div class="result-name">${escapeHtml(name)}</div><div class="result-meta">${oldSize?`<span class="result-old num">${fileSize(oldSize)}</span>`:''}${newSize?`<span class="result-new num">${fileSize(newSize)}</span>`:''}${pct!==undefined?`<span class="result-pct">${pct}</span>`:''}${extra?`<span class="result-new num">${escapeHtml(extra)}</span>`:''}<button class="result-dl" type="button" aria-label="Download"><i class="ti ti-download"></i></button></div>`;$('button',r).addEventListener('click',()=>download(blob,filename||name));rows.appendChild(r);}
async function imageToBlob(file,{mime='image/jpeg',quality=.82,width=null,height=null,crop=false}={}){const bmp=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=width||bmp.width;canvas.height=height||bmp.height;const ctx=canvas.getContext('2d',{alpha:mime==='image/png'});if(crop){const sr=bmp.width/bmp.height,dr=canvas.width/canvas.height;let sx=0,sy=0,sw=bmp.width,sh=bmp.height;if(sr>dr){sw=bmp.height*dr;sx=(bmp.width-sw)/2}else{sh=bmp.width/dr;sy=(bmp.height-sh)/2}ctx.drawImage(bmp,sx,sy,sw,sh,0,0,canvas.width,canvas.height)}else ctx.drawImage(bmp,0,0,canvas.width,canvas.height);bmp.close&&bmp.close();return new Promise((res,rej)=>canvas.toBlob(b=>b?res(b):rej(new Error('Canvas export failed')),mime,quality));}
function extForMime(m){return m==='image/png'?'png':m==='image/webp'?'webp':'jpg'}
function baseName(n){return String(n).replace(/\.[^.]+$/,'')}
function tool(slug,title,category,india,meta,icon,render,opts={}){TOOLS[slug]={slug,title,category,india,region:opts.region||(india?'IN':null),meta,icon,render,desc:opts.desc||meta,subcategory:opts.subcategory||category,howTo:opts.howTo||['Enter or upload your data in the tool area above.','Adjust the available options for your required output.','Download, copy, or read the result directly in your browser.'],faqs:opts.faqs||[{q:'Is this tool free?',a:'Yes. It runs in your browser and does not require login, upload, or subscription.'},{q:'Does my data leave my device?',a:'No. Processing happens locally in your browser whenever the tool can use browser APIs.'}]};}
function normalizePath(path=window.location.pathname){let p=String(path||'/').replace(/\/{2,}/g,'/');if(!p.startsWith('/'))p='/'+p;if(p!=='/'&&!p.endsWith('/'))p+='/';return p;}
function toolPath(slug){return `/tool/${encodeURIComponent(slug)}/`;}
function canonicalUrl(path=normalizePath()){return `https://toolcrunch.app${path}`;}
function navigate(path,{replace=false}={}){const target=normalizePath(path);const current=normalizePath();if(target===current){router();return;}history[replace?'replaceState':'pushState']({},'',target);router();window.scrollTo({top:0,behavior:'auto'});}
function migrateLegacyHash(){const legacy=window.location.hash.replace('#','').trim();if(!legacy)return;let target=null;if(legacy==='home')target='/';else if(['privacy','about','contact'].includes(legacy))target=`/${legacy}/`;else if(TOOLS[legacy])target=toolPath(legacy);if(target){history.replaceState({},'',target);}}
function renderCatBar(){const bar=$('#cat-bar');bar.innerHTML='';PILLS.forEach(p=>{const b=document.createElement('button');b.className='cat-pill'+(p===activeFilter?' active':'');b.textContent=p;b.addEventListener('click',()=>{activeFilter=p;if(normalizePath()!=='/')navigate('/');else{renderCatBar();renderGrid();}});bar.appendChild(b);});}
function showHome(){const home=$('#home'),page=$('#tool-page');page.hidden=true;home.hidden=false;home.innerHTML=`<div class="home-hero"><div class="eyebrow">46 tools, zero upload</div><h1>Do the thing,<br>get the file.</h1><p class="hero-sub">Image compression, PDF editing, developer utilities, and file converters — all running in your browser. Your files never leave your device.</p></div><div class="trust-strip"><span>Runs locally in your browser</span><span>No file size limits</span><span>No account needed</span></div>${ad('HOME')}<div id="home-tools"></div>`;renderCatBar();renderGrid();}
function filteredTools(){const q=$('#search')?.value.trim().toLowerCase()||'';return Object.values(TOOLS).filter(t=>{const inCat=activeFilter==='All'||t.category===activeFilter||(CATEGORIES[activeFilter]||[]).includes(t.slug);const hit=!q||[t.title,t.meta,t.category,t.subcategory,t.slug].join(' ').toLowerCase().includes(q);const regionOk=!(t.region==='IN'&&activeFilter==='All'&&!q);return inCat&&hit&&regionOk;});}
function appendToolCard(grid,t){const a=document.createElement('a');a.href=toolPath(t.slug);a.className='tool-card'+(t.india?' india':'');a.innerHTML=`<span class="tool-card-dot"></span><span class="tool-card-name">${escapeHtml(t.title.split(' — ')[0])}</span><span class="tool-card-sub">${escapeHtml(t.subcategory)}</span>`;grid.appendChild(a);}
function renderFlatTools(mount,list,title,q){mount.innerHTML=`<div class="section-head"><h2>${escapeHtml(title)}</h2><span class="section-count">${list.length}</span></div>`;if(!list.length){mount.insertAdjacentHTML('beforeend',`<div class="no-results">No tools match "<em>${escapeHtml(q)}</em>"</div>`);return;}const grid=document.createElement('div');grid.className='tool-grid';list.forEach(t=>appendToolCard(grid,t));mount.appendChild(grid);}
function renderGrid(){const mount=$('#home-tools');if(!mount)return;const q=$('#search').value.trim();const list=filteredTools();mount.innerHTML='';if(q||activeFilter!=='All'){renderFlatTools(mount,list,q?'Search results':activeFilter,q);return;}const total=list.length;mount.insertAdjacentHTML('beforeend',`<div class="section-head"><h2>Browse by category</h2><span class="section-count">${total}</span></div>`);PILLS.filter(p=>p!=='All').forEach(cat=>{const tools=list.filter(t=>t.category===cat||(CATEGORIES[cat]||[]).includes(t.slug));if(!tools.length)return;const section=document.createElement('section');section.className='category-section';section.innerHTML=`<div class="section-head"><h2>${escapeHtml(cat)}</h2><span class="section-count">${tools.length}</span></div>`;const grid=document.createElement('div');grid.className='tool-grid';tools.forEach(t=>appendToolCard(grid,t));section.appendChild(grid);mount.appendChild(section);});}
function showToolPage(tool){const home=$('#home'),page=$('#tool-page');home.hidden=true;page.hidden=false;page.innerHTML=`<nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span class="breadcrumb-sep" aria-hidden="true">/</span><a href="/" data-filter="${escapeHtml(tool.category)}">${escapeHtml(tool.category)}</a><span class="breadcrumb-sep" aria-hidden="true">/</span><span>${escapeHtml(tool.title)}</span></nav><div class="tool-header"><div class="eyebrow">${escapeHtml(tool.category)} · ${escapeHtml(tool.subcategory)}</div><h1>${escapeHtml(tool.title)}</h1><p class="tool-desc">${escapeHtml(tool.desc)}</p></div>${ad('TOP')}<div id="tool-body"></div>${ad('MID')}<section class="seo-content how-to"><h2>How to use</h2><ol>${tool.howTo.map(s=>`<li>${escapeHtml(s)}</li>`).join('')}</ol></section><section class="seo-content"><h2>Frequently asked questions</h2><div class="faq-list">${tool.faqs.map(f=>`<div class="faq-item"><div class="faq-q"><span>${escapeHtml(f.q)}</span><i class="ti ti-chevron-down" aria-hidden="true"></i></div><div class="faq-a">${escapeHtml(f.a)}</div></div>`).join('')}</div></section>${privacy()}${ad('BOT')}`;$$('.faq-q',page).forEach(q=>q.addEventListener('click',()=>q.parentElement.classList.toggle('open')));const cat=$('.breadcrumb a[data-filter]',page);cat.addEventListener('click',()=>{activeFilter=tool.category;});tool.render($('#tool-body'));}
function updateMeta(title,desc,path=normalizePath(),noindex=false){document.title=title;document.querySelector('meta[name="description"]').content=desc;document.querySelector('meta[property="og:title"]').content=title;document.querySelector('meta[property="og:description"]').content=desc;const url=canonicalUrl(path);const canon=document.querySelector('link[rel="canonical"]');if(canon)canon.href=url;const ogUrl=document.querySelector('meta[property="og:url"]');if(ogUrl)ogUrl.content=url;const robots=document.querySelector('meta[name="robots"]');if(robots)robots.content=noindex?'noindex, follow':'index, follow';}
function injectSchema(tool){document.querySelectorAll('script[data-schema]').forEach(s=>s.remove());const url=canonicalUrl(toolPath(tool.slug));const schemas=[{"@context":"https://schema.org","@type":"SoftwareApplication","name":tool.title,"url":url,"operatingSystem":"Web Browser","applicationCategory":"UtilitiesApplication","offers":{"@type":"Offer","price":"0","priceCurrency":"INR"},"description":tool.meta},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://toolcrunch.app/"},{"@type":"ListItem","position":2,"name":tool.title,"item":url}]}];if(tool.faqs&&tool.faqs.length){schemas.push({"@context":"https://schema.org","@type":"FAQPage","mainEntity":tool.faqs.map(f=>({"@type":"Question","name":f.q,"acceptedAnswer":{"@type":"Answer","text":f.a}}))});}schemas.forEach(schema=>{const s=document.createElement('script');s.type='application/ld+json';s.dataset.schema='1';s.textContent=JSON.stringify(schema);document.head.appendChild(s);});}

const STATIC_PAGES={privacy:{title:'Privacy Policy',desc:'Privacy Policy for toolcrunch.app. Files never leave your device because tools run locally in your browser.',html:`<h1>Privacy Policy</h1><p>Last updated: ${new Date().toLocaleDateString('en-IN')}</p><h2>What we collect</h2><p>ToolCrunch does not collect, store, or transmit any files you use with our tools. All processing happens locally in your browser. We do not have access to your data.</p><h2>Analytics</h2><p>We may use aggregate analytics to understand usage patterns such as page views and device types.</p><h2>Advertising</h2><p>We use or may use Google AdSense to show advertisements. Google and its advertising partners may use cookies or similar technologies where permitted. Visitors in regions that require consent may be shown a consent message before personalised advertising or related storage is used.</p><h2>Cookies and local storage</h2><p>ToolCrunch stores your theme preference in localStorage. Advertising, analytics, and consent providers may use their own cookies or storage subject to applicable consent requirements.</p><h2>Contact</h2><p>Questions: <a href="mailto:contact@toolcrunch.app">contact@toolcrunch.app</a></p>`},about:{title:'About ToolCrunch',desc:'About toolcrunch.app, a collection of free private browser-based utility tools.',html:`<h1>About ToolCrunch</h1><p>ToolCrunch is a collection of 46 free online tools for image compression, PDF editing, developer utilities, text tools, file converters, QR codes, and calculators.</p><p>Most file tools run entirely in your browser. Your files, images, and data never leave your device and are never uploaded to our server.</p><h2>Why we built this</h2><p>Most online tools upload your files, hide basic features behind paywalls, or require account creation. We think useful tools should be free, private, and fast.</p>`},contact:{title:'Contact',desc:'Contact toolcrunch.app for bug reports, feature requests, and questions.',html:`<h1>Contact</h1><p>Email: <a href="mailto:contact@toolcrunch.app">contact@toolcrunch.app</a></p><p>For bug reports, feature requests, or general questions about ToolCrunch.</p>`}};
function showStatic(key){const p=STATIC_PAGES[key];if(!p)return showHome();document.querySelectorAll('script[data-schema]').forEach(s=>s.remove());const page=$('#tool-page'),home=$('#home');home.hidden=true;page.hidden=false;page.innerHTML=`<div class="static-page"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span class="breadcrumb-sep" aria-hidden="true">/</span><span>${escapeHtml(p.title)}</span></nav>${p.html}</div>`;updateMeta(`${p.title} — ToolCrunch`,p.desc,`/${key}/`);}
function showNotFound(){document.querySelectorAll('script[data-schema]').forEach(s=>s.remove());const page=$('#tool-page'),home=$('#home');home.hidden=true;page.hidden=false;page.innerHTML=`<div class="static-page"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span class="breadcrumb-sep" aria-hidden="true">/</span><span>Not found</span></nav><h1>Page not found</h1><p>The requested ToolCrunch page does not exist.</p><p style="margin-top:16px"><a class="btn btn-primary" href="/">Back to all tools</a></p></div>`;updateMeta('Page not found — ToolCrunch','The requested ToolCrunch page does not exist.',normalizePath(),true);}
function router(){document.querySelectorAll('script[data-schema]').forEach(s=>s.remove());const path=normalizePath();if(path==='/'){showHome();updateMeta('ToolCrunch — 46 free online tools. No upload, no login.','Free online tools for image compression, PDF editing, developer utilities, file converters, QR codes, and calculators. Private by design — most tools run directly in your browser.','/');return;}const staticMatch=path.match(/^\/(privacy|about|contact)\/$/);if(staticMatch){showStatic(staticMatch[1]);return;}const toolMatch=path.match(/^\/tool\/([^/]+)\/$/);if(toolMatch){const slug=decodeURIComponent(toolMatch[1]);const t=TOOLS[slug];if(t){showToolPage(t);updateMeta(`${t.title} — ToolCrunch`,t.meta,toolPath(t.slug));injectSchema(t);return;}}showNotFound();}
window.addEventListener('popstate',router);
document.addEventListener('click',e=>{if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const a=e.target.closest('a[href]');if(!a||a.target==='_blank'||a.hasAttribute('download'))return;const url=new URL(a.href,window.location.href);if(url.origin!==window.location.origin||!url.pathname.startsWith('/'))return;if(url.pathname==='/'&&!a.dataset.filter){activeFilter='All';const search=$('#search');if(search)search.value='';}e.preventDefault();navigate(url.pathname);});
$('#search').addEventListener('input',debounce(()=>{activeFilter='All';if(normalizePath()!=='/')navigate('/');renderCatBar();renderGrid();},200));
$('#theme-toggle').addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('theme',dark?'dark':'light');$('#theme-toggle i').className=dark?'ti ti-sun':'ti ti-moon';});const savedTheme=localStorage.getItem('theme');if(savedTheme){document.documentElement.dataset.theme=savedTheme;$('#theme-toggle i').className=savedTheme==='dark'?'ti ti-sun':'ti ti-moon';}

function renderImageCompressor(c){let quality=.78,format='Same',items=[];c.innerHTML='';const controls=document.createElement('div');controls.className='controls';controls.innerHTML='<div><label class="ctrl-label">Quality</label><input id="q" type="range" min="10" max="95" value="78"><div class="ctrl-meta"><span>Smaller</span><span class="ctrl-val">78%</span></div></div><div><label class="ctrl-label">Output format</label><div id="fmt"></div></div>';controls.querySelector('#q').addEventListener('input',e=>{quality=e.target.value/100;controls.querySelector('.ctrl-val').textContent=e.target.value+'%'});controls.querySelector('#fmt').appendChild(pillGroup(['Same','JPEG','PNG','WebP'],'Same',v=>format=v));const dz=makeDropZone('image/*',handle,true);const results=rowsContainer('Compressed files','Ready');const rows=$('.result-rows',results);const all=document.createElement('button');all.className='btn btn-primary';all.innerHTML='<i class="ti ti-file-zip"></i>Download all as ZIP';all.disabled=true;all.addEventListener('click',async()=>{await injectScript(CDN.zip);const zip=new JSZip();items.forEach(x=>zip.file(x.filename,x.blob));download(await zip.generateAsync({type:'blob'}),'compressed-images.zip')});c.append(dz,controls,results,all);async function handle(files){rows.innerHTML='';items=[];for(const file of [...files]){try{if(!file.type.startsWith('image/')){showError(c,'Please upload an image file.');continue}let mime=file.type;if(format==='JPEG')mime='image/jpeg';if(format==='PNG')mime='image/png';if(format==='WebP')mime='image/webp';if(format==='Same'&&!['image/jpeg','image/png','image/webp'].includes(mime))mime='image/jpeg';const blob=await imageToBlob(file,{mime,quality});const filename=baseName(file.name)+'.'+extForMime(mime);items.push({blob,filename});const pct=Math.round((1-blob.size/file.size)*100);addResultRow(rows,{name:file.name,oldSize:file.size,newSize:blob.size,pct:(pct>=0?'−':'')+Math.abs(pct)+'%',blob,filename});}catch(e){showError(c,'Image too large to process. Try a smaller file.')}}all.disabled=!items.length;const avg=items.length?Math.round(items.reduce((s,x,i)=>s+(1-x.blob.size/[...files][i].size),0)/items.length*100):0;$('.results-summary',results).textContent=items.length?`Avg −${avg}%`:'Ready';}}
tool('image-compressor','Image compressor — compress JPG, PNG, WebP online free','Image',false,'Compress JPG, PNG, and WebP images online without losing quality. Reduce file size by up to 90%. No upload — runs entirely in your browser. Free and instant.','ti-photo',renderImageCompressor,{subcategory:'Compression',howTo:['Drop your image files into the area above or click Browse files to select them.','Adjust the quality slider — 75–80% gives the best balance of size and quality.','Click the download arrow next to each file or Download all as ZIP for batch.'],faqs:[{q:'Does my image get uploaded to a server?',a:'No. Image compression uses the HTML5 Canvas API in your browser. Your images never leave your device and are never stored anywhere.'},{q:'What formats does this support?',a:'Upload JPG, JPEG, PNG, WebP, GIF, BMP, and AVIF. Output can be JPEG, PNG, or WebP.'},{q:'How much can I compress without losing visible quality?',a:'For most photos, 70–82% quality is indistinguishable from the original at normal viewing. For graphics and screenshots, 85–90% is safer.'},{q:'Is there a file size limit?',a:'Limited only by your device available RAM. Works with files up to 50 MB on most devices.'}]});

const EXAM_PRESETS={'SSC CGL / CHSL / MTS':{photo:{w:200,h:230,minKB:20,maxKB:50},sig:{w:140,h:60,minKB:10,maxKB:20}},'UPSC Civil Services':{photo:{w:300,h:350,minKB:20,maxKB:300},sig:{w:300,h:100,minKB:20,maxKB:300}},'RRB NTPC / Group D':{photo:{w:200,h:200,minKB:20,maxKB:50},sig:{w:200,h:100,minKB:10,maxKB:20}},'IBPS PO / Clerk':{photo:{w:200,h:230,minKB:20,maxKB:50},sig:{w:140,h:60,minKB:10,maxKB:20}},'SBI PO / Clerk':{photo:{w:200,h:200,minKB:20,maxKB:50},sig:{w:140,h:60,minKB:10,maxKB:20}},'NEET UG':{photo:{w:134,h:170,minKB:10,maxKB:200},sig:{w:134,h:57,minKB:10,maxKB:200}},'JEE Main':{photo:{w:200,h:240,minKB:4,maxKB:40},sig:{w:160,h:60,minKB:1,maxKB:30}},'CUET UG / PG':{photo:{w:200,h:230,minKB:10,maxKB:200},sig:{w:200,h:80,minKB:5,maxKB:30}},'India Post GDS':{photo:{w:320,h:400,minKB:30,maxKB:100},sig:{w:300,h:120,minKB:20,maxKB:100}},'UPSC NDA / CDS':{photo:{w:200,h:230,minKB:20,maxKB:50},sig:{w:140,h:60,minKB:10,maxKB:20}},'State PSC (General)':{photo:{w:200,h:230,minKB:20,maxKB:100},sig:{w:200,h:80,minKB:10,maxKB:50}},Custom:{photo:null,sig:null}};
async function resizeAndTarget(file,targetW,targetH,minKB,maxKB){let lo=.1,hi=.95,bestBlob=null;const bmp=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=targetW;canvas.height=targetH;const ctx=canvas.getContext('2d');const srcRatio=bmp.width/bmp.height,dstRatio=targetW/targetH;let sx=0,sy=0,sw=bmp.width,sh=bmp.height;if(srcRatio>dstRatio){sw=bmp.height*dstRatio;sx=(bmp.width-sw)/2}else{sh=bmp.width/dstRatio;sy=(bmp.height-sh)/2}ctx.drawImage(bmp,sx,sy,sw,sh,0,0,targetW,targetH);bmp.close&&bmp.close();for(let i=0;i<8;i++){const mid=(lo+hi)/2;const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',mid));if(blob.size<=maxKB*1024){bestBlob=blob;lo=mid}else hi=mid}return bestBlob||await new Promise(r=>canvas.toBlob(r,'image/jpeg',.1));}
function renderExam(c){c.innerHTML=`<div class="field"><label>Select exam preset</label><select id="exam">${Object.keys(EXAM_PRESETS).map(k=>`<option>${k}</option>`).join('')}</select></div><div class="field-grid-2" style="margin-top:16px"><div class="tool-panel"><h3>Photo</h3><div id="photoSpec" class="tool-card-sub"></div><div id="photoDz"></div><div id="photoOut"></div></div><div class="tool-panel"><h3>Signature</h3><div id="sigSpec" class="tool-card-sub"></div><div id="sigDz"></div><div id="sigOut"></div></div></div>`;const exam=$('#exam',c),photoSpec=$('#photoSpec',c),sigSpec=$('#sigSpec',c);function specText(s){return s?`Required: ${s.w}×${s.h} px · ${s.minKB}–${s.maxKB} KB · JPG`:'Custom preset needs manual dimensions in a later revision.'}function sync(){const p=EXAM_PRESETS[exam.value];photoSpec.textContent=specText(p.photo);sigSpec.textContent=specText(p.sig)}sync();exam.addEventListener('change',sync);async function handle(kind,file){const p=EXAM_PRESETS[exam.value][kind];const out=$('#'+(kind==='photo'?'photoOut':'sigOut'),c);out.innerHTML='';if(!p){showError(out,'Choose a non-custom preset.');return}try{const blob=await resizeAndTarget(file,p.w,p.h,p.minKB,p.maxKB);const filename=kind==='photo'?'photo.jpg':'signature.jpg';out.innerHTML=`<div class="calc-result"><div class="calc-stat-label">Result</div><div class="calc-stat-value success num">${fileSize(blob.size)} · ${p.w}×${p.h} px</div><button class="btn btn-primary btn-sm" style="margin-top:12px"><i class="ti ti-download"></i>Download ${filename}</button>${blob.size<p.minKB*1024?`<div class="warn-state">Result is ${fileSize(blob.size)} — use a higher resolution original photo.</div>`:''}</div>`;$('button',out).addEventListener('click',()=>download(blob,filename));}catch(e){showError(out,'Image too large to process. Try a smaller file.')}}$('#photoDz',c).appendChild(makeDropZone('image/*',fs=>handle('photo',fs[0]),false,'Drop photo here','JPG, PNG, WebP — original camera file preferred'));$('#sigDz',c).appendChild(makeDropZone('image/*',fs=>handle('sig',fs[0]),false,'Drop signature here','JPG, PNG, WebP — clear scan preferred'));}
tool('exam-photo-resizer','Exam photo resizer — SSC, UPSC, RRB, IBPS, NEET photo size','Image',true,'Resize and compress photo and signature for Indian government exams. One-click presets for SSC CGL, UPSC, RRB NTPC, IBPS PO, NEET, JEE, State PSC. Free, private, no upload.','ti-id',renderExam,{subcategory:'Indian exams',howTo:['Select your exam from the dropdown at the top.','Upload your passport-size photo and signature image. Use original camera photos — avoid WhatsApp-forwarded copies or screenshots.','The tool auto-resizes to the exact dimensions and compresses to the required KB range. Download photo.jpg and signature.jpg.'],faqs:[{q:'Is my photo stored anywhere?',a:'No. All resizing and compression happens in your browser using the Canvas API. Your photos never leave your device and are never stored or transmitted.'},{q:'My photo got rejected by the portal. What should I do?',a:'Ensure you are uploading the original camera file, not a WhatsApp-forwarded copy, screenshot, or already-resized image.'},{q:'Which exams are supported?',a:'SSC, UPSC, RRB, IBPS, SBI, NEET, JEE, CUET, India Post GDS, and most State PSC-style requirements are included.'}]});

function renderImageResizer(c){let file=null,bmpInfo=null,ratio=1,mode='Pixels',lock=true;c.innerHTML='<div id="dz"></div><div id="form" hidden><div class="calc-result"><div id="orig" class="calc-stat-label"></div></div><div class="controls"><div><label class="ctrl-label">Mode</label><div id="mode"></div></div><div><label class="ctrl-label">Options</label><label><input id="lock" type="checkbox" checked> Lock aspect ratio</label></div></div><div id="pixel" class="field-grid-2"><div class="field"><label>Width</label><input id="w" type="number"></div><div class="field"><label>Height</label><input id="h" type="number"></div></div><div id="percent" class="field" hidden><label>Percentage</label><input id="pct" type="number" value="50"></div><div class="btn-row"><button id="go" class="btn btn-primary"><i class="ti ti-download"></i>Resize and download</button></div></div>';$('#dz',c).appendChild(makeDropZone('image/*',async fs=>{file=fs[0];const b=await createImageBitmap(file);bmpInfo={w:b.width,h:b.height};ratio=b.width/b.height;b.close&&b.close();$('#form',c).hidden=false;$('#orig',c).textContent=`Original: ${bmpInfo.w} × ${bmpInfo.h} px`;$('#w',c).value=bmpInfo.w;$('#h',c).value=bmpInfo.h},false));$('#mode',c).appendChild(pillGroup(['Pixels','Percentage'],'Pixels',v=>{mode=v;$('#pixel',c).hidden=v!=='Pixels';$('#percent',c).hidden=v!=='Percentage'}));$('#lock',c).addEventListener('change',e=>lock=e.target.checked);$('#w',c).addEventListener('input',e=>{if(lock)$('#h',c).value=Math.round(+e.target.value/ratio)});$('#h',c).addEventListener('input',e=>{if(lock)$('#w',c).value=Math.round(+e.target.value*ratio)});$('#go',c).addEventListener('click',async()=>{if(!file)return showError(c,'No files selected. Drop a file or click Browse files.');let w=+$('#w',c).value,h=+$('#h',c).value;if(mode==='Percentage'){w=Math.round(bmpInfo.w*(+$('#pct',c).value/100));h=Math.round(bmpInfo.h*(+$('#pct',c).value/100));}const mime=['image/jpeg','image/png','image/webp'].includes(file.type)?file.type:'image/jpeg';const blob=await imageToBlob(file,{mime,quality:.9,width:w,height:h});download(blob,`${baseName(file.name)}-${w}x${h}.${extForMime(mime)}`);});}
tool('image-resizer','Image resizer — resize images online free (px or %)','Image',false,'Resize images online by exact pixels or percentage. Maintain aspect ratio. Supports JPG, PNG, WebP. No server upload — runs in browser. Free and instant.','ti-arrows-maximize',renderImageResizer,{subcategory:'Resize'});

function renderHeic(c){showLoading(c);injectScript(CDN.heic).then(()=>{c.innerHTML='<div id="dz"></div><div id="progress" class="tool-card-sub" style="margin-top:12px"></div>';const res=rowsContainer('Converted files','Ready'),rows=$('.result-rows',res);c.appendChild(res);$('#dz',c).appendChild(makeDropZone('.heic,.heif,image/heic,image/heif',async files=>{rows.innerHTML='';let i=0;for(const file of [...files].slice(0,20)){i++;$('#progress',c).textContent=`Converting ${i} of ${files.length}...`;try{const blob=await heic2any({blob:file,toType:'image/jpeg',quality:.92});addResultRow(rows,{name:file.name,oldSize:file.size,newSize:blob.size,blob,filename:baseName(file.name)+'.jpg'});}catch(e){showError(c,'Please upload a HEIC file.')}}$('#progress',c).textContent='Done';},true,'Drop HEIC photos here','HEIC/HEIF iPhone photos — batch up to 20 files'));}).catch(()=>showError(c,"Couldn't load tool component. Check your internet connection."));}
tool('heic-to-jpg','HEIC to JPG converter — convert iPhone photos free','Image',false,'Convert HEIC photos from iPhone to JPG or PNG online. Free, no server upload, works in browser. Batch convert up to 20 files. Download instantly.','ti-photo-scan',renderHeic,{subcategory:'Conversion'});

function renderImageToPdf(c){showLoading(c);injectScript(CDN.jsPDF).then(()=>{let files=[];c.innerHTML='<div id="dz"></div><div class="controls"><div class="field"><label>Page size</label><select id="size"><option>A4</option><option>Letter</option><option>Auto-fit</option></select></div><div class="field"><label>Orientation</label><select id="ori"><option>Portrait</option><option>Landscape</option></select></div></div><div id="list" class="list"></div><button id="go" class="btn btn-primary"><i class="ti ti-file-type-pdf"></i>Create PDF</button>';function drawList(){const l=$('#list',c);l.innerHTML='';files.forEach((f,i)=>{const d=document.createElement('div');d.className='file-item';d.innerHTML=`<span class="result-name">${escapeHtml(f.name)}</span><span><button class="btn btn-secondary btn-sm" data-up="${i}">Up</button> <button class="btn btn-secondary btn-sm" data-down="${i}">Down</button></span>`;l.appendChild(d);});$$('[data-up]',l).forEach(b=>b.onclick=()=>{const i=+b.dataset.up;if(i>0){[files[i-1],files[i]]=[files[i],files[i-1]];drawList();}});$$('[data-down]',l).forEach(b=>b.onclick=()=>{const i=+b.dataset.down;if(i<files.length-1){[files[i+1],files[i]]=[files[i],files[i+1]];drawList();}})}$('#dz',c).appendChild(makeDropZone('image/*',fs=>{files=[...files,...fs].filter(f=>f.type.startsWith('image/'));drawList();},true));$('#go',c).onclick=async()=>{if(!files.length)return showError(c,'No files selected. Drop a file or click Browse files.');const {jsPDF}=window.jspdf;const size=$('#size',c).value,ori=$('#ori',c).value.toLowerCase()[0];let pdf=null;for(const f of files){const bmp=await createImageBitmap(f);const data=await new Promise(r=>{const canvas=document.createElement('canvas');canvas.width=bmp.width;canvas.height=bmp.height;canvas.getContext('2d').drawImage(bmp,0,0);r(canvas.toDataURL('image/jpeg',.92));});let format=size==='Auto-fit'?[bmp.width,bmp.height]:size.toLowerCase();if(!pdf)pdf=new jsPDF({orientation:ori,unit:'pt',format});else pdf.addPage(format,ori);const w=pdf.internal.pageSize.getWidth(),h=pdf.internal.pageSize.getHeight();const scale=Math.min(w/bmp.width,h/bmp.height);const iw=bmp.width*scale,ih=bmp.height*scale;pdf.addImage(data,'JPEG',(w-iw)/2,(h-ih)/2,iw,ih);bmp.close&&bmp.close();}download(pdf.output('blob'),'images.pdf');};}).catch(()=>showError(c,"Couldn't load tool component. Check your internet connection."));}
tool('image-to-pdf','Image to PDF converter — JPG PNG to PDF online free','Image',false,'Convert JPG, PNG, WebP images to a PDF file online. Drag to reorder images. Choose A4, Letter, or auto page size. Free, no signup, runs in browser.','ti-file-type-pdf',renderImageToPdf,{subcategory:'PDF'});
function renderWebP(c){let quality=.82;c.innerHTML='<div id="dz"></div><div class="controls"><div><label class="ctrl-label">Quality</label><input id="q" type="range" min="40" max="95" value="82"><div class="ctrl-meta"><span>Smaller</span><span class="ctrl-val">82%</span></div></div></div>';const res=rowsContainer('Converted files','Ready'),rows=$('.result-rows',res);c.appendChild(res);$('#q',c).oninput=e=>{quality=e.target.value/100;$('.ctrl-val',c).textContent=e.target.value+'%'};$('#dz',c).appendChild(makeDropZone('image/*',async files=>{rows.innerHTML='';for(const f of [...files]){try{const blob=await imageToBlob(f,{mime:'image/webp',quality});addResultRow(rows,{name:f.name,oldSize:f.size,newSize:blob.size,blob,filename:baseName(f.name)+'.webp'});}catch(e){showError(c,"Your browser doesn't support WebP export. Try Chrome or Edge.")}}},true));}
tool('webp-converter','WebP converter — convert JPG PNG to WebP online free','Image',false,'Convert JPG and PNG images to WebP format online. Reduce file size by 30–50%. Free, instant, no server upload. Supports batch conversion.','ti-file-type-svg',renderWebP,{subcategory:'Conversion'});
function renderExif(c){showLoading(c);injectScript(CDN.piexif).then(()=>{c.innerHTML='<div id="dz"></div><div id="out"></div>';$('#dz',c).appendChild(makeDropZone('image/jpeg,.jpg,.jpeg',fs=>{const f=fs[0];const out=$('#out',c);out.innerHTML='';const reader=new FileReader();reader.onload=()=>{try{const data=reader.result;const ex=piexif.load(data);const removed=[];if(ex.GPS&&Object.keys(ex.GPS).length)removed.push('GPS coordinates');if(ex['0th'][piexif.ImageIFD.Make]||ex['0th'][piexif.ImageIFD.Model])removed.push('Camera make/model');if(ex.Exif&&ex.Exif[piexif.ExifIFD.DateTimeOriginal])removed.push('Date taken');if(ex['0th'][piexif.ImageIFD.Software])removed.push('Software');if(ex['0th'][piexif.ImageIFD.Orientation])removed.push('Orientation');const clean=piexif.remove(data);const arr=clean.split(',');const mime=(arr[0].match(/:(.*?);/)||[])[1]||'image/jpeg';const bstr=atob(arr[1]||'');const u8arr=new Uint8Array(bstr.length);for(let i=0;i<bstr.length;i++)u8arr[i]=bstr.charCodeAt(i);const blob=new Blob([u8arr],{type:mime});out.innerHTML=`<div class="calc-result"><div class="calc-stat-label">Removed metadata</div><div class="output">${removed.length?removed.map(x=>'• '+x).join('\n'):'No EXIF metadata found'}</div><button class="btn btn-primary" style="margin-top:12px"><i class="ti ti-download"></i>Download clean JPG</button></div>`;$('button',out).onclick=()=>download(blob,baseName(f.name)+'-clean.jpg');}catch(e){showError(out,'Please upload a JPG file.')}};reader.readAsDataURL(f);},false));}).catch(()=>showError(c,"Couldn't load tool component. Check your internet connection."));}
tool('exif-remover','EXIF data remover — strip photo metadata online free','Image',false,'Remove GPS location, camera model, date, and all metadata from photos before sharing online. Free, private, runs entirely in your browser. Supports JPG.','ti-shield-off',renderExif,{subcategory:'Privacy'});

async function ensurePdfLib(){await injectScript(CDN.pdfLib);return PDFLib}
function renderPdfCompressor(c){showLoading(c);ensurePdfLib().then(()=>{let mode='Fast',dpi=96,file=null;c.innerHTML='<div id="dz"></div><div class="controls"><div><label class="ctrl-label">Compression mode</label><div id="mode"></div></div><div id="dpiBox"><label class="ctrl-label">DPI for deep mode</label><div id="dpi"></div></div></div><div class="warn-state" id="note" hidden>Each page is re-rendered as an image. Text becomes non-selectable in the output. Use Fast mode if you need selectable text.</div><button id="go" class="btn btn-primary"><i class="ti ti-file-zip"></i>Compress PDF</button><div id="out"></div>';$('#mode',c).appendChild(pillGroup(['Fast','Deep'],'Fast',v=>{mode=v;$('#note',c).hidden=v!=='Deep'}));$('#dpi',c).appendChild(pillGroup(['72','96','150'],'96',v=>dpi=+v));$('#dz',c).appendChild(makeDropZone('application/pdf,.pdf',fs=>{file=fs[0];toast(file.name)},false));$('#go',c).onclick=async()=>{if(!file)return showError(c,'No files selected. Drop a file or click Browse files.');const out=$('#out',c);out.innerHTML='';try{let blob;if(mode==='Fast'){const doc=await PDFLib.PDFDocument.load(await file.arrayBuffer(),{ignoreEncryption:true});doc.setTitle('');doc.setSubject('');doc.setCreator('ToolCrunch');const bytes=await doc.save({useObjectStreams:true});blob=new Blob([bytes],{type:'application/pdf'});}else{const pdfjs=await loadPdfJs();const src=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;const ndoc=await PDFLib.PDFDocument.create();for(let p=1;p<=src.numPages;p++){const page=await src.getPage(p);const viewport=page.getViewport({scale:dpi/72});const canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;const jpg=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.75));const img=await ndoc.embedJpg(await jpg.arrayBuffer());const pg=ndoc.addPage([viewport.width,viewport.height]);pg.drawImage(img,{x:0,y:0,width:viewport.width,height:viewport.height});}blob=new Blob([await ndoc.save()],{type:'application/pdf'});}out.innerHTML='<div class="results"><div class="result-rows"></div></div>';addResultRow($('.result-rows',out),{name:file.name,oldSize:file.size,newSize:blob.size,pct:'Done',blob,filename:baseName(file.name)+'-compressed.pdf'});}catch(e){showError(out,'This PDF is password-protected or cannot be processed. Remove the password first.')}};});}
tool('pdf-compressor','PDF compressor — reduce PDF file size online free','PDF',false,'Compress PDF files to reduce size without losing quality. No server upload — runs in browser using pdf-lib. Free, instant, supports files up to 100 MB.','ti-file-zip',renderPdfCompressor,{subcategory:'Compression'});
function renderPdfMerger(c){showLoading(c);ensurePdfLib().then(()=>{let files=[];c.innerHTML='<div id="dz"></div><div id="list" class="list"></div><button id="go" class="btn btn-primary"><i class="ti ti-files"></i>Merge PDFs</button>';function list(){const l=$('#list',c);l.innerHTML='';files.forEach((f,i)=>{const d=document.createElement('div');d.className='file-item';d.innerHTML=`<span class="result-name">${escapeHtml(f.name)}</span><span><button class="btn btn-secondary btn-sm" data-up="${i}">Up</button> <button class="btn btn-secondary btn-sm" data-del="${i}">Remove</button></span>`;l.appendChild(d);});$$('[data-up]',l).forEach(b=>b.onclick=()=>{const i=+b.dataset.up;if(i>0){[files[i-1],files[i]]=[files[i],files[i-1]];list();}});$$('[data-del]',l).forEach(b=>b.onclick=()=>{files.splice(+b.dataset.del,1);list();});}$('#dz',c).appendChild(makeDropZone('application/pdf,.pdf',fs=>{files=[...files,...fs];list();},true));$('#go',c).onclick=async()=>{if(!files.length)return showError(c,'No files selected. Drop a file or click Browse files.');try{const merged=await PDFLib.PDFDocument.create();for(const f of files){const doc=await PDFLib.PDFDocument.load(await f.arrayBuffer(),{ignoreEncryption:true});const pages=await merged.copyPages(doc,doc.getPageIndices());pages.forEach(p=>merged.addPage(p));}download(new Blob([await merged.save()],{type:'application/pdf'}),'merged.pdf');}catch(e){showError(c,'This PDF is password-protected. Remove the password first.')}};});}
tool('pdf-merger','PDF merger — combine PDF files online free','PDF',false,'Merge multiple PDF files into one document online. Drag to reorder. Free, no upload, runs in browser. Combine up to 20 PDFs instantly.','ti-files',renderPdfMerger,{subcategory:'Merge'});
function parseRanges(s,max){return s.split(',').map(x=>x.trim()).filter(Boolean).map(part=>{const [a,b]=part.split('-').map(Number);const start=Math.max(1,a||1),end=Math.min(max,b||a||max);return [start,end];});}
function renderPdfSplitter(c){showLoading(c);ensurePdfLib().then(()=>{let file=null,doc=null,mode='Individual';c.innerHTML='<div id="dz"></div><div id="info" class="calc-result" hidden></div><div class="controls"><div><label class="ctrl-label">Mode</label><div id="mode"></div></div><div class="field"><label>Page ranges</label><input id="ranges" value="1-3, 5, 7-9"></div></div><button id="go" class="btn btn-primary"><i class="ti ti-cut"></i>Split PDF</button><div id="out"></div>';$('#mode',c).appendChild(pillGroup(['Individual','Ranges'],'Individual',v=>mode=v));$('#dz',c).appendChild(makeDropZone('application/pdf,.pdf',async fs=>{file=fs[0];doc=await PDFLib.PDFDocument.load(await file.arrayBuffer(),{ignoreEncryption:true});$('#info',c).hidden=false;$('#info',c).innerHTML=`This PDF has <span class="num">${doc.getPageCount()}</span> pages`;},false));$('#go',c).onclick=async()=>{if(!doc)return showError(c,'No files selected. Drop a file or click Browse files.');await injectScript(CDN.zip);const zip=new JSZip(),max=doc.getPageCount();const ranges=mode==='Individual'?Array.from({length:max},(_,i)=>[i+1,i+1]):parseRanges($('#ranges',c).value,max);for(const [a,b] of ranges){const nd=await PDFLib.PDFDocument.create();const pages=await nd.copyPages(doc,Array.from({length:b-a+1},(_,i)=>a-1+i));pages.forEach(p=>nd.addPage(p));zip.file(`pages-${a}-${b}.pdf`,await nd.save());}download(await zip.generateAsync({type:'blob'}),'split-pdf.zip');};});}
tool('pdf-splitter','PDF splitter — split PDF pages online free','PDF',false,'Split a PDF into individual pages or by page ranges. Free, no server upload. Download split pages as separate PDFs or as a ZIP file.','ti-cut',renderPdfSplitter,{subcategory:'Split'});
function renderPdfToImages(c){c.innerHTML='<div id="dz"></div><div class="controls"><div><label class="ctrl-label">DPI</label><div id="dpi"></div></div><div><label class="ctrl-label">Format</label><div id="fmt"></div></div></div><div id="thumbs" class="list"></div><button id="zip" class="btn btn-primary" disabled><i class="ti ti-file-zip"></i>Download all as ZIP</button>';let dpi=150,fmt='JPG',imgs=[];$('#dpi',c).appendChild(pillGroup(['72','150','300'],'150',v=>dpi=+v));$('#fmt',c).appendChild(pillGroup(['JPG','PNG'],'JPG',v=>fmt=v));$('#dz',c).appendChild(makeDropZone('application/pdf,.pdf',async fs=>{const pdfjs=await loadPdfJs();const pdf=await pdfjs.getDocument({data:await fs[0].arrayBuffer()}).promise;imgs=[];$('#thumbs',c).innerHTML='';for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p),vp=page.getViewport({scale:dpi/72}),canvas=document.createElement('canvas');canvas.width=vp.width;canvas.height=vp.height;await page.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;const type=fmt==='PNG'?'image/png':'image/jpeg';const blob=await new Promise(r=>canvas.toBlob(r,type,.9));imgs.push({blob,name:`page-${p}.${fmt.toLowerCase()}`});const url=URL.createObjectURL(blob);$('#thumbs',c).insertAdjacentHTML('beforeend',`<div class="file-item"><span>Page ${p}</span><img src="${url}" style="width:60px;border:0.5px solid var(--border);border-radius:4px"></div>`);}$('#zip',c).disabled=false;},false));$('#zip',c).onclick=async()=>{await injectScript(CDN.zip);const zip=new JSZip();imgs.forEach(i=>zip.file(i.name,i.blob));download(await zip.generateAsync({type:'blob'}),'pdf-images.zip')};}
tool('pdf-to-images','PDF to images — convert PDF pages to JPG or PNG free','PDF',false,'Convert PDF pages to high-quality JPG or PNG images online. Choose DPI and format. Free, no upload, renders in browser. Download all as ZIP.','ti-photo',renderPdfToImages,{subcategory:'Conversion'});

function makeQr(el,text,size=220,fg='#18181B',bg='#FFFFFF',level='M'){el.innerHTML='';return new QRCode(el,{text:text||' ',width:size,height:size,colorDark:fg,colorLight:bg,correctLevel:QRCode.CorrectLevel[level]});}
function renderQr(c){showLoading(c);injectScript(CDN.qr).then(()=>{let type='URL';c.innerHTML='<div class="controls"><div><label class="ctrl-label">QR type</label><div id="types"></div></div><div><label class="ctrl-label">Size</label><input id="size" type="range" min="128" max="512" value="220"><div class="ctrl-meta"><span>128</span><span class="ctrl-val">220px</span></div></div></div><div id="form" class="tool-panel"></div><div class="field-grid-2"><div class="field"><label>Foreground</label><input id="fg" type="color" value="#18181B"></div><div class="field"><label>Background</label><input id="bg" type="color" value="#FFFFFF"></div></div><div class="calc-result"><div id="qr" style="display:flex;justify-content:center"></div><button id="dl" class="btn btn-primary" style="margin-top:16px"><i class="ti ti-download"></i>Download PNG</button></div>';$('#types',c).appendChild(pillGroup(['URL','Text','WiFi','Email','Phone','SMS','WhatsApp','UPI'],'URL',v=>{type=v;drawForm();update()}));function drawForm(){const f=$('#form',c);const common={URL:'<div class="field"><label>URL</label><input id="v" type="url" value="https://toolcrunch.app"></div>',Text:'<div class="field"><label>Text</label><textarea id="v">Hello from ToolCrunch</textarea></div>',WiFi:'<div class="field-grid-2"><div class="field"><label>SSID</label><input id="ssid"></div><div class="field"><label>Password</label><input id="pass"></div></div><div class="field"><label>Security</label><select id="sec"><option>WPA</option><option>WEP</option><option>nopass</option></select></div>',Email:'<div class="field"><label>Email</label><input id="email" type="email"></div><div class="field"><label>Subject</label><input id="sub"></div>',Phone:'<div class="field"><label>Phone</label><input id="phone"></div>',SMS:'<div class="field"><label>Phone</label><input id="phone"></div><div class="field"><label>Message</label><textarea id="msg"></textarea></div>',WhatsApp:'<div class="field"><label>Phone with country code</label><input id="phone" value="91"></div><div class="field"><label>Message</label><textarea id="msg"></textarea></div>',UPI:'<div class="field-grid-2"><div class="field"><label>UPI ID</label><input id="pa"></div><div class="field"><label>Name</label><input id="pn"></div></div><div class="field"><label>Amount</label><input id="am" type="number"></div>'};f.innerHTML=common[type];$$('input,textarea,select',f).forEach(x=>x.addEventListener('input',debounce(update,300)));}function value(){if(type==='URL'||type==='Text')return $('#v',c).value;if(type==='WiFi')return `WIFI:S:${$('#ssid',c).value};T:${$('#sec',c).value};P:${$('#pass',c).value};;`;if(type==='Email')return `mailto:${$('#email',c).value}?subject=${encodeURIComponent($('#sub',c).value)}`;if(type==='Phone')return `tel:${$('#phone',c).value}`;if(type==='SMS')return `sms:${$('#phone',c).value}?body=${encodeURIComponent($('#msg',c).value)}`;if(type==='WhatsApp')return `https://wa.me/${$('#phone',c).value}?text=${encodeURIComponent($('#msg',c).value)}`;return `upi://pay?pa=${encodeURIComponent($('#pa',c).value)}&pn=${encodeURIComponent($('#pn',c).value)}&am=${encodeURIComponent($('#am',c).value)}&cu=INR`;}function update(){const size=+$('#size',c).value;$('.ctrl-val',c).textContent=size+'px';makeQr($('#qr',c),value(),size,$('#fg',c).value,$('#bg',c).value)}drawForm();['size','fg','bg'].forEach(id=>$('#'+id,c).addEventListener('input',debounce(update,300)));$('#dl',c).onclick=()=>{const img=$('#qr img',c)||$('#qr canvas',c);if(img.tagName==='IMG')fetch(img.src).then(r=>r.blob()).then(b=>download(b,'qr-code.png'));else img.toBlob(b=>download(b,'qr-code.png'));};update();});}
tool('qr-generator','QR code generator — free QR code maker online','QR',false,'Generate QR codes for URLs, text, WiFi, email, phone, SMS, WhatsApp, and UPI payment. Download PNG. No signup, no watermark, free.','ti-qrcode',renderQr,{subcategory:'Generator'});
function renderUpi(c){showLoading(c);injectScript(CDN.qr).then(()=>{c.innerHTML='<div class="field-grid-2"><div class="field"><label>UPI ID</label><input id="pa" placeholder="name@bank"></div><div class="field"><label>Your name</label><input id="pn"></div></div><div class="field-grid-2"><div class="field"><label>Amount optional</label><input id="am" type="number"></div><div class="field"><label>Transaction note optional</label><input id="tn"></div></div><div class="calc-result"><div id="qr" style="display:flex;justify-content:center"></div><div id="str" class="output mono" style="margin-top:12px"></div><button id="dl" class="btn btn-primary" style="margin-top:12px"><i class="ti ti-download"></i>Download PNG</button></div>';function update(){const s=`upi://pay?pa=${encodeURIComponent($('#pa',c).value)}&pn=${encodeURIComponent($('#pn',c).value)}&am=${encodeURIComponent($('#am',c).value)}&cu=INR&tn=${encodeURIComponent($('#tn',c).value)}`;$('#str',c).textContent=s;makeQr($('#qr',c),s,260)}$$('input',c).forEach(i=>i.addEventListener('input',debounce(update,300)));$('#dl',c).onclick=()=>{const img=$('#qr img',c)||$('#qr canvas',c);if(img.tagName==='IMG')fetch(img.src).then(r=>r.blob()).then(b=>download(b,'upi-qr.png'));else img.toBlob(b=>download(b,'upi-qr.png'));};update();});}
tool('upi-qr','UPI QR code generator — payment QR for business free','QR',true,'Generate a UPI payment QR code for your shop or personal account. Enter UPI ID, name, and optional fixed amount. Download PNG instantly. Free.','ti-qrcode',renderUpi,{subcategory:'India payments'});

function renderGST(c){let rate=18,mode='Add GST',type='Intra-state';c.innerHTML='<div class="field"><label>Amount</label><input id="amt" type="number" value="10000"></div><div class="controls"><div><label class="ctrl-label">GST rate</label><div id="rate"></div><input id="custom" type="number" hidden style="margin-top:8px" value="18"></div><div><label class="ctrl-label">Mode</label><div id="mode"></div></div></div><div><label class="ctrl-label">Transaction type</label><div id="type"></div></div><div id="out"></div>';$('#rate',c).appendChild(pillGroup(['5%','12%','18%','28%','Custom'],'18%',v=>{if(v==='Custom'){$('#custom',c).hidden=false;rate=+$('#custom',c).value}else{$('#custom',c).hidden=true;rate=parseFloat(v)}calc()}));$('#mode',c).appendChild(pillGroup(['Add GST','Remove GST'],'Add GST',v=>{mode=v;calc()}));$('#type',c).appendChild(pillGroup(['Intra-state','Inter-state'],'Intra-state',v=>{type=v;calc()}));$('#custom',c).oninput=e=>{rate=+e.target.value;calc()};$('#amt',c).oninput=debounce(calc,150);function calc(){const a=+$('#amt',c).value||0;let original,gst,total;if(mode==='Add GST'){original=a;gst=a*rate/100;total=a+gst}else{total=a;original=a/(1+rate/100);gst=total-original}const stats=[{label:'Original amount',value:rupee(original)},{label:'GST amount',value:rupee(gst)},{label:'Total amount',value:rupee(total),cls:'accent'}];if(type==='Intra-state'){stats.push({label:'CGST',value:rupee(gst/2)},{label:'SGST',value:rupee(gst/2)})}else stats.push({label:'IGST',value:rupee(gst)});$('#out',c).innerHTML=statGrid(stats)}calc();}
tool('gst-calculator','GST calculator — add or remove GST online free India','Calculators',true,'Calculate GST for any amount in India. Add or remove 5%, 12%, 18%, 28% GST. Shows CGST, SGST, and IGST breakdown. Free, instant.','ti-receipt-tax',renderGST,{subcategory:'Tax'});
function renderEMI(c){c.innerHTML='<div class="field-grid-3"><div class="field"><label>Loan amount</label><input id="p" type="number" value="1000000"></div><div class="field"><label>Interest rate %</label><input id="r" type="number" step="0.1" value="8.5"></div><div class="field"><label>Tenure years</label><input id="y" type="number" value="20"></div></div><div id="out"></div><button id="toggle" class="btn btn-secondary">Show schedule</button><div id="schedule" hidden></div>';function calcEMI(P,annualRate,months){if(annualRate===0)return P/months;const R=annualRate/12/100;return P*R*Math.pow(1+R,months)/(Math.pow(1+R,months)-1)}function calc(){const P=+$('#p',c).value||0,r=+$('#r',c).value||0,m=(+$('#y',c).value||0)*12,emi=calcEMI(P,r,m),pay=emi*m,int=pay-P;$('#out',c).innerHTML=statGrid([{label:'Monthly EMI',value:rupee(emi),cls:'accent'},{label:'Total Interest',value:rupee(int)},{label:'Total Payment',value:rupee(pay)},{label:'Interest %',value:num(int/P*100,1)+'%'}]);let bal=P,html='<div class="results"><div class="results-header"><div class="results-title">Amortisation schedule</div></div>';for(let i=1;i<=Math.min(m,360);i++){const intr=bal*r/12/100,prin=emi-intr;bal=Math.max(0,bal-prin);html+=`<div class="result-row"><span>Month ${i}</span><span class="num">${rupee(prin)} principal · ${rupee(intr)} interest · ${rupee(bal)} balance</span></div>`}$('#schedule',c).innerHTML=html+'</div>'}$$('input',c).forEach(i=>i.oninput=debounce(calc,150));$('#toggle',c).onclick=()=>{$('#schedule',c).hidden=!$('#schedule',c).hidden};calc();}
tool('emi-calculator','EMI calculator — home loan, car loan EMI calculator India','Calculators',true,'Calculate monthly EMI for home loan, car loan, or personal loan. See total interest payable and amortisation schedule. Indian rupee format. Free online EMI calculator.','ti-building-bank',renderEMI,{subcategory:'Finance'});
function renderSIP(c){c.innerHTML='<div class="field-grid-3"><div class="field"><label>Monthly SIP</label><input id="m" type="number" value="10000"></div><div class="field"><label>Annual return %</label><input id="r" type="number" value="12"></div><div class="field"><label>Duration years</label><input id="y" type="number" value="15"></div></div><div id="out"></div><canvas id="bar" height="36" style="width:100%;margin-top:16px"></canvas>';function calcSIP(monthly,annualRate,years){const months=years*12,r=annualRate/12/100,FV=monthly*((Math.pow(1+r,months)-1)/r)*(1+r),invested=monthly*months;return{invested,returns:FV-invested,maturity:FV}}function calc(){const v=calcSIP(+$('#m',c).value||0,+$('#r',c).value||0,+$('#y',c).value||0);$('#out',c).innerHTML=statGrid([{label:'Invested amount',value:rupee(v.invested)},{label:'Est. returns',value:rupee(v.returns),cls:'success'},{label:'Maturity value',value:rupee(v.maturity),cls:'accent'}]);const canvas=$('#bar',c),ctx=canvas.getContext('2d'),w=canvas.width=canvas.clientWidth*devicePixelRatio,h=canvas.height=36*devicePixelRatio;ctx.clearRect(0,0,w,h);ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--border').trim();ctx.fillRect(0,0,w,h);ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--ink').trim();ctx.fillRect(0,0,w*(v.invested/v.maturity||0),h);ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--success').trim();ctx.fillRect(w*(v.invested/v.maturity||0),0,w,h)}$$('input',c).forEach(i=>i.oninput=debounce(calc,150));calc();}
tool('sip-calculator','SIP calculator — monthly SIP returns calculator India','Calculators',true,'Calculate SIP returns for mutual fund investments. Enter monthly SIP amount, expected return rate, and duration. See maturity amount and wealth gained. Free.','ti-chart-line',renderSIP,{subcategory:'Finance'});
function slabTax(income,slabs){let tax=0,prev=0;for(const [limit,rate] of slabs){const amt=Math.max(0,Math.min(income,limit)-prev);tax+=amt*rate;prev=limit;if(income<=limit)break}return tax}
function renderTax(c){c.innerHTML='<div class="field"><label>Gross annual income</label><input id="income" type="number" value="1200000"></div><h3 style="margin-top:16px">Old regime deductions</h3><div class="field-grid-3"><div class="field"><label>80C</label><input id="c80" type="number" value="150000"></div><div class="field"><label>80D</label><input id="d80" type="number" value="25000"></div><div class="field"><label>HRA exempt</label><input id="hra" type="number" value="0"></div><div class="field"><label>24b interest</label><input id="b24" type="number" value="0"></div><div class="field"><label>Other deductions</label><input id="other" type="number" value="0"></div></div><div id="out"></div><div class="warn-state">Simplified surcharge note: surcharge can apply above ₹50 lakh; this calculator focuses on normal slab comparison.</div>';function calc(){const inc=+$('#income',c).value||0;const newInc=Math.max(0,inc-75000);let newTax=slabTax(newInc,[[300000,0],[700000,.05],[1000000,.10],[1200000,.15],[1500000,.20],[Infinity,.30]]);if(newInc<=700000)newTax=0;newTax*=1.04;const ded=Math.min(+$('#c80',c).value||0,150000)+Math.min(+$('#d80',c).value||0,25000)+(+$('#hra',c).value||0)+Math.min(+$('#b24',c).value||0,200000)+(+$('#other',c).value||0);const oldInc=Math.max(0,inc-50000-ded);let oldTax=slabTax(oldInc,[[250000,0],[500000,.05],[1000000,.20],[Infinity,.30]]);if(oldInc<=500000)oldTax=Math.max(0,oldTax-12500);oldTax*=1.04;const diff=Math.abs(newTax-oldTax),rec=newTax<oldTax?`New regime saves you ${rupee(diff)}`:oldTax<newTax?`Old regime saves you ${rupee(diff)}`:'Both regimes are equal';$('#out',c).innerHTML=statGrid([{label:'New regime tax',value:rupee(newTax),cls:newTax<oldTax?'success':''},{label:'Old regime tax',value:rupee(oldTax),cls:oldTax<newTax?'success':''},{label:'Recommendation',value:rec,cls:'accent'}])}$$('input',c).forEach(i=>i.oninput=debounce(calc,150));calc();}
tool('income-tax-calculator','Income tax calculator India 2024-25 — old vs new regime','Calculators',true,'Calculate income tax under old and new regime for FY 2024-25. Compare both, see which saves more. Includes 80C, 80D, HRA, standard deduction. Free.','ti-file-invoice',renderTax,{subcategory:'Tax'});
function renderCGPA(c){const formulas={'Standard (CGPA × 9.5)':x=>x*9.5,'Anna University':x=>x>=8.5?x*10-7.5:x*10-5,'VTU':x=>x*9.5,'Mumbai University':x=>(x-.75)*10,'JNTU':x=>x*10,'4-point scale':x=>x*25,'5-point scale':x=>x*20,'Custom (CGPA × multiplier)':null};c.innerHTML=`<div class="field-grid-2"><div class="field"><label>CGPA</label><input id="cgpa" type="number" step="0.01" value="8.2"></div><div class="field"><label>Formula</label><select id="formula">${Object.keys(formulas).map(k=>`<option>${k}</option>`).join('')}</select></div></div><div class="field" id="multBox" hidden><label>Multiplier</label><input id="mult" type="number" value="9.5"></div><div id="out"></div>`;function calc(){const f=$('#formula',c).value,x=+$('#cgpa',c).value||0;$('#multBox',c).hidden=!f.startsWith('Custom');const pct=formulas[f]?formulas[f](x):x*(+$('#mult',c).value||9.5);const cls=pct>=75?'First Class with Distinction':pct>=60?'First Class':pct>=45?'Second Class':'Pass';$('#out',c).innerHTML=statGrid([{label:'Percentage',value:num(pct,2)+'%',cls:'accent'},{label:'Classification',value:cls}])}$$('input,select',c).forEach(i=>i.oninput=calc);calc();}
tool('cgpa-to-percentage','CGPA to percentage calculator — 10 point scale converter India','Calculators',true,'Convert CGPA to percentage for Indian universities. Supports standard ×9.5, Anna University, VTU, Mumbai University, and custom formulas. Free instant calculator.','ti-school',renderCGPA,{subcategory:'Education'});
function diffYMD(a,b){let y=b.getFullYear()-a.getFullYear(),m=b.getMonth()-a.getMonth(),d=b.getDate()-a.getDate();if(d<0){m--;d+=new Date(b.getFullYear(),b.getMonth(),0).getDate()}if(m<0){y--;m+=12}return{y,m,d}}
function renderAge(c){const today=new Date().toISOString().slice(0,10);c.innerHTML=`<div class="field-grid-2"><div class="field"><label>Date of birth</label><input id="dob" type="date" value="2000-01-01"></div><div class="field"><label>As of date</label><input id="asof" type="date" value="${today}"></div></div><div id="out"></div>`;function calc(){const dob=new Date($('#dob',c).value),asof=new Date($('#asof',c).value);if(isNaN(dob)||isNaN(asof))return;const v=diffYMD(dob,asof),days=Math.floor((asof-dob)/86400000);let nb=new Date(asof.getFullYear(),dob.getMonth(),dob.getDate());if(nb<asof)nb.setFullYear(nb.getFullYear()+1);$('#out',c).innerHTML=statGrid([{label:'Exact age',value:`${v.y} years ${v.m} months ${v.d} days`,cls:'accent'},{label:'Total days',value:num(days,0)},{label:'Next birthday',value:`${Math.ceil((nb-asof)/86400000)} days`}])}$$('input',c).forEach(i=>i.oninput=calc);calc();}
tool('age-calculator','Age calculator — calculate exact age online free','Calculators',false,'Calculate your exact age in years, months, and days. Find age between two dates. See next birthday countdown. Free online age calculator.','ti-calendar',renderAge,{subcategory:'Date'});
function renderBMI(c){c.innerHTML='<div class="field-grid-2"><div class="field"><label>Height cm</label><input id="h" type="number" value="175"></div><div class="field"><label>Weight kg</label><input id="w" type="number" value="70"></div></div><div id="out"></div>';function calc(){const h=(+$('#h',c).value||0)/100,w=+$('#w',c).value||0,bmi=w/(h*h);const cat=bmi<18.5?'Underweight':bmi<23?'Normal (Indian)':bmi<25?'Overweight (Indian)':'Obese (Indian)';$('#out',c).innerHTML=statGrid([{label:'BMI',value:num(bmi,1),cls:'accent'},{label:'Category',value:cat},{label:'Healthy weight range',value:`${num(18.5*h*h,1)}–${num(22.9*h*h,1)} kg`}])}$$('input',c).forEach(i=>i.oninput=calc);calc();}
tool('bmi-calculator','BMI calculator — body mass index calculator free','Calculators',false,'Calculate BMI instantly. Enter height and weight in metric or imperial. See BMI category and Indian-specific healthy weight range. Free online BMI calculator.','ti-ruler-measure',renderBMI,{subcategory:'Health'});
function renderPercentage(c){let mode='X% of Y';c.innerHTML='<div><label class="ctrl-label">Mode</label><div id="mode"></div></div><div class="field-grid-2" style="margin-top:16px"><div class="field"><label>Value X</label><input id="x" type="number" value="20"></div><div class="field"><label>Value Y</label><input id="y" type="number" value="100"></div></div><div id="out"></div>';$('#mode',c).appendChild(pillGroup(['X% of Y','X is % of Y','% change'],'X% of Y',v=>{mode=v;calc()}));function calc(){const x=+$('#x',c).value||0,y=+$('#y',c).value||0;let ans=mode==='X% of Y'?x*y/100:mode==='X is % of Y'?x/y*100:(y-x)/x*100;$('#out',c).innerHTML=statGrid([{label:'Answer',value:num(ans,2)+(mode==='X% of Y'?'':'%'),cls:'accent'}])}$$('input',c).forEach(i=>i.oninput=calc);calc();}
tool('percentage-calculator','Percentage calculator — calculate % online free','Calculators',false,'Three percentage calculators: what is X% of Y, X is what % of Y, and % change between two values. Free, instant, no app needed.','ti-percentage',renderPercentage,{subcategory:'Math'});
function renderCompound(c){c.innerHTML='<div class="field-grid-3"><div class="field"><label>Principal</label><input id="p" type="number" value="100000"></div><div class="field"><label>Rate %</label><input id="r" type="number" value="8"></div><div class="field"><label>Years</label><input id="t" type="number" value="10"></div></div><div class="field"><label>Compounding</label><select id="n"><option value="365">Daily</option><option value="12">Monthly</option><option value="4">Quarterly</option><option value="2">Half-yearly</option><option value="1">Annually</option></select></div><div id="out"></div>';function calc(){const P=+$('#p',c).value||0,r=(+$('#r',c).value||0)/100,t=+$('#t',c).value||0,n=+$('#n',c).value;const A=P*Math.pow(1+r/n,n*t);$('#out',c).innerHTML=statGrid([{label:'Total amount',value:rupee(A),cls:'accent'},{label:'Interest earned',value:rupee(A-P),cls:'success'}])}$$('input,select',c).forEach(i=>i.oninput=calc);calc();}
