function renderDiscount(c){let mode='Apply discount';c.innerHTML='<div><label class="ctrl-label">Mode</label><div id="mode"></div></div><div class="field-grid-2" style="margin-top:16px"><div class="field"><label>Value 1</label><input id="a" type="number" value="1000"></div><div class="field"><label>Value 2 / discount %</label><input id="b" type="number" value="20"></div></div><div id="out"></div>';$('#mode',c).appendChild(pillGroup(['Apply discount','Find original','Find discount %'],'Apply discount',v=>{mode=v;calc()}));function calc(){const a=+$('#a',c).value||0,b=+$('#b',c).value||0;let stats;if(mode==='Apply discount'){stats=[{label:'Final price',value:rupee(a*(1-b/100)),cls:'accent'},{label:'Savings',value:rupee(a*b/100),cls:'success'}]}else if(mode==='Find original'){stats=[{label:'Original price',value:rupee(a/(1-b/100)),cls:'accent'}]}else stats=[{label:'Discount',value:num((a-b)/a*100,2)+'%',cls:'accent'},{label:'Savings',value:rupee(a-b),cls:'success'}];$('#out',c).innerHTML=statGrid(stats)}$$('input',c).forEach(i=>i.oninput=calc);calc();}
