function renderTip(c){let tip=10,round=false;c.innerHTML='<div class="field-grid-2"><div class="field"><label>Bill total</label><input id="bill" type="number" value="1000"></div><div class="field"><label>People</label><input id="people" type="number" value="2"></div></div><div><label class="ctrl-label">Tip %</label><div id="tip"></div><input id="custom" type="number" hidden></div><label style="display:block;margin-top:12px"><input id="round" type="checkbox"> Round up per person</label><div id="out"></div>';$('#tip',c).appendChild(pillGroup(['0','5','10','15','18','20','Custom'],'10',v=>{if(v==='Custom'){$('#custom',c).hidden=false;tip=+$('#custom',c).value||0}else{$('#custom',c).hidden=true;tip=+v}calc()}));$('#custom',c).oninput=e=>{tip=+e.target.value||0;calc()};$('#round',c).onchange=e=>{round=e.target.checked;calc()};function calc(){const bill=+$('#bill',c).value||0,people=+$('#people',c).value||1,t=bill*tip/100,total=bill+t,each=round?Math.ceil(total/people):total/people;$('#out',c).innerHTML=statGrid([{label:'Tip amount',value:rupee(t)},{label:'Total bill',value:rupee(total),cls:'accent'},{label:'Per person',value:rupee(each),cls:'success'},{label:'Tip per person',value:rupee(t/people)}])}$$('input',c).forEach(i=>i.oninput=calc);calc();}
