const UNITS={Length:{Kilometer:1,Meter:1000,Centimeter:100000,Millimeter:1e6,Micrometer:1e9,Mile:.621371,Yard:1093.61,Foot:3280.84,Inch:39370.1,'Nautical mile':.539957},Weight:{Kilogram:1,Gram:1000,Milligram:1e6,Tonne:.001,Pound:2.20462,Ounce:35.274,Stone:.157473,'US ton':.00110231},Temperature:'special',Data:{Byte:1,Kilobyte:1/1024,Megabyte:1/1048576,Gigabyte:1/1073741824,Terabyte:1/1099511627776,Petabyte:1/1125899906842624,Bit:8,Kilobit:8/1024,Megabit:8/1048576},Speed:{'km/h':1,'m/s':1/3.6,mph:.621371,knot:.539957,'ft/s':.911344},Area:{'sq meter':1,'sq kilometer':1e-6,'sq centimeter':10000,'sq foot':10.7639,'sq inch':1550,Hectare:1e-4,Acre:.000247105,'sq mile':3.861e-7,'sq yard':1.19599},Volume:{Liter:1,Milliliter:1000,'Cubic meter':.001,'Cubic foot':.0353147,'Gallon (US)':.264172,'Gallon (UK)':.219969,'Fluid oz (US)':33.814,Cup:4.22675}};
function convertTemp(val,from,to){let c;if(from==='Celsius')c=val;else if(from==='Fahrenheit')c=(val-32)*5/9;else c=val-273.15;if(to==='Celsius')return c;if(to==='Fahrenheit')return c*9/5+32;return c+273.15}
function renderUnit(c){let cat='Length';c.innerHTML='<div><label class="ctrl-label">Category</label><div id="cats"></div></div><div class="field-grid-3" style="margin-top:16px"><div class="field"><label>Value</label><input id="val" type="number" value="1"></div><div class="field"><label>From</label><select id="from"></select></div><div class="field"><label>To</label><select id="to"></select></div></div><div id="out"></div>';$('#cats',c).appendChild(pillGroup(Object.keys(UNITS),'Length',v=>{cat=v;fill();calc()}));function fill(){const units=cat==='Temperature'?['Celsius','Fahrenheit','Kelvin']:Object.keys(UNITS[cat]);$('#from',c).innerHTML=units.map(u=>`<option>${u}</option>`).join('');$('#to',c).innerHTML=units.map(u=>`<option>${u}</option>`).join('');$('#to',c).selectedIndex=1}function calc(){const v=+$('#val',c).value||0,from=$('#from',c).value,to=$('#to',c).value;let out=cat==='Temperature'?convertTemp(v,from,to):(v/UNITS[cat][from])*UNITS[cat][to];$('#out',c).innerHTML=statGrid([{label:'Converted value',value:`${num(out,6)} ${escapeHtml(to)}`,cls:'accent'}])}fill();$$('input,select',c).forEach(i=>i.oninput=calc);calc();}
