function renderPasswordGenerator(c){c.innerHTML='<div class="field"><label>Length</label><input id="len" type="range" min="8" max="64" value="20"><div class="ctrl-meta"><span>8</span><span class="ctrl-val">20</span></div></div><div class="field-grid-2"><label><input id="up" type="checkbox" checked> Uppercase</label><label><input id="lo" type="checkbox" checked> Lowercase</label><label><input id="nu" type="checkbox" checked> Numbers</label><label><input id="sy" type="checkbox" checked> Symbols</label><label><input id="amb" type="checkbox"> Exclude ambiguous</label></div><div class="btn-row"><button id="gen" class="btn btn-primary">Generate</button><button id="copy" class="btn btn-secondary">Copy</button><button id="bulk" class="btn btn-secondary">Generate 10</button></div><div id="out" class="output mono" style="margin-top:16px"></div><div id="strength" class="calc-result"></div>';const sets={up:'ABCDEFGHJKLMNPQRSTUVWXYZ',lo:'abcdefghijkmnopqrstuvwxyz',nu:'23456789',sy:'!@#$%^&*()-_=+[]{};:,.?'};function one(){let chars='';['up','lo','nu','sy'].forEach(id=>{if($('#'+id,c).checked)chars+=sets[id]});if(!chars)chars=sets.lo;let arr=new Uint32Array(+$('#len',c).value);crypto.getRandomValues(arr);return [...arr].map(n=>chars[n%chars.length]).join('')}function gen(n=1){const list=Array.from({length:n},one);$('#out',c).textContent=list.join('\n');const score=Math.min(6,Math.floor(+$('#len',c).value/8)+['up','lo','nu','sy'].filter(id=>$('#'+id,c).checked).length-1);$('#strength',c).innerHTML=statGrid([{label:'Strength',value:['Weak','Fair','Good','Strong','Very Strong','Very Strong'][Math.max(0,score-1)]||'Weak',cls:score>=4?'success':'accent'}])}$('#len',c).oninput=e=>{$('.ctrl-val',c).textContent=e.target.value;gen()};$('#gen',c).onclick=()=>gen();$('#bulk',c).onclick=()=>gen(10);$('#copy',c).onclick=()=>copyText($('#out',c).textContent);$$('input[type="checkbox"]',c).forEach(i=>i.onchange=()=>gen());gen();}
