function renderJson(c){let indent=2;c.innerHTML='<textarea id="in" class="mono" placeholder="Paste JSON here"></textarea><div class="btn-row"><button id="fmt" class="btn btn-primary">Format</button><button id="min" class="btn btn-secondary">Minify</button><button id="val" class="btn btn-secondary">Validate</button><button id="copy" class="btn btn-secondary">Copy</button><button id="clear" class="btn btn-secondary">Clear</button></div><div style="margin-top:8px"><label class="ctrl-label">Indent</label><div id="indent"></div></div><div id="out" class="output mono" style="margin-top:16px"></div>';$('#indent',c).appendChild(pillGroup(['2 spaces','4 spaces','Tab'],'2 spaces',v=>{indent=v==='Tab'?'\t':v==='4 spaces'?4:2}));function parse(){return JSON.parse($('#in',c).value)}function run(type){try{const obj=parse();$('#out',c).textContent=type==='min'?JSON.stringify(obj):type==='val'?'Valid JSON':JSON.stringify(obj,null,indent);toast('Valid JSON','success')}catch(e){$('#out',c).innerHTML='';showError($('#out',c),e.message)}}$('#fmt',c).onclick=()=>run('fmt');$('#min',c).onclick=()=>run('min');$('#val',c).onclick=()=>run('val');$('#copy',c).onclick=()=>copyText($('#out',c).textContent);$('#clear',c).onclick=()=>{$('#in',c).value='';$('#out',c).textContent=''};}
