function renderBase64(c){let mode='Text encode';c.innerHTML='<div><label class="ctrl-label">Mode</label><div id="mode"></div></div><textarea id="in" class="mono" style="margin-top:16px"></textarea><div id="dz"></div><div class="btn-row"><button id="go" class="btn btn-primary">Run</button><button id="copy" class="btn btn-secondary">Copy</button><button id="dl" class="btn btn-secondary">Download file</button></div><div id="out" class="output mono" style="margin-top:16px"></div><div id="preview"></div>';$('#mode',c).appendChild(pillGroup(['Text encode','Text decode','File → Base64','Base64 → File'],'Text encode',v=>{mode=v;$('#dz',c).hidden=!v.startsWith('File');}));$('#dz',c).appendChild(makeDropZone('*/*',fs=>{const r=new FileReader();r.onload=()=>{$('#out',c).textContent=r.result};r.readAsDataURL(fs[0]);},false));$('#go',c).onclick=()=>{try{const s=$('#in',c).value;$('#out',c).textContent=mode==='Text encode'?btoa(unescape(encodeURIComponent(s))):mode==='Text decode'?decodeURIComponent(escape(atob(s))):s;}catch(e){showError(c,'Invalid Base64 input.')}};$('#copy',c).onclick=()=>copyText($('#out',c).textContent);$('#dl',c).onclick=()=>{const s=$('#in',c).value||$('#out',c).textContent;const b=mode==='Base64 → File'?new Blob([Uint8Array.from(atob(s.split(',').pop()),m=>m.charCodeAt(0))]):new Blob([s]);download(b,'base64-output.bin')};$('#dz',c).hidden=true;}
