function renderHash(c){showLoading(c);injectScript(CDN.crypto).then(()=>{c.innerHTML='<textarea id="txt" class="mono" placeholder="Text to hash"></textarea><div class="field-grid-3"><label><input type="checkbox" value="MD5" checked> MD5</label><label><input type="checkbox" value="SHA1" checked> SHA1</label><label><input type="checkbox" value="SHA256" checked> SHA256</label><label><input type="checkbox" value="SHA384"> SHA384</label><label><input type="checkbox" value="SHA512"> SHA512</label></div><div class="field"><label>Compare hash optional</label><input id="cmp"></div><div id="out" class="list"></div>';function calc(){const s=$('#txt',c).value,cmp=$('#cmp',c).value.trim().toLowerCase(),out=$('#out',c);out.innerHTML='';$$('input[type="checkbox"]:checked',c).forEach(ch=>{const h=CryptoJS[ch.value](s).toString();out.insertAdjacentHTML('beforeend',`<div class="file-item"><div><b>${ch.value}</b><div class="mono" style="word-break:break-all">${h}</div>${cmp?`<span class="result-pct">${cmp===h?'Match':'Mismatch'}</span>`:''}</div><button class="btn btn-secondary btn-sm" data-copy="${h}">Copy</button></div>`)});$$('[data-copy]',out).forEach(b=>b.onclick=()=>copyText(b.dataset.copy));}$$('textarea,input',c).forEach(i=>i.oninput=debounce(calc,150));calc();});}
