function uuidv4(){if(crypto.randomUUID)return crypto.randomUUID();const b=new Uint8Array(16);crypto.getRandomValues(b);b[6]=b[6]&15|64;b[8]=b[8]&63|128;return [...b].map((x,i)=>(i===4||i===6||i===8||i===10?'-':'')+x.toString(16).padStart(2,'0')).join('')}
function renderUUID(c){c.innerHTML='<div class="field"><label>Quantity</label><input id="qty" type="number" min="1" max="1000" value="1"></div><div class="btn-row"><button id="gen" class="btn btn-primary">Generate</button><button id="copy" class="btn btn-secondary">Copy all</button><button id="dl" class="btn btn-secondary">Download .txt</button></div><textarea id="out" class="mono" style="margin-top:16px"></textarea>';function gen(){const n=Math.max(1,Math.min(1000,+$('#qty',c).value||1));$('#out',c).value=Array.from({length:n},uuidv4).join('\n')}$('#gen',c).onclick=gen;$('#copy',c).onclick=()=>copyText($('#out',c).value);$('#dl',c).onclick=()=>download(new Blob([$('#out',c).value],{type:'text/plain'}),'uuids.txt');gen();}
