function renderTimestamp(c){c.innerHTML='<div id="now" class="calc-result"></div><div class="field-grid-2"><div class="field"><label>Timestamp</label><input id="ts" type="number"></div><div class="field"><label>Unit</label><select id="unit"><option>seconds</option><option>milliseconds</option></select></div></div><div id="out1"></div><div class="field"><label>Date to timestamp</label><input id="dt" type="datetime-local"></div><div id="out2"></div>';function tick(){const s=Math.floor(Date.now()/1000);$('#now',c).innerHTML=`Current Unix timestamp: <span class="num">${s}</span>`}setInterval(tick,1000);tick();function calc1(){let v=+$('#ts',c).value||Math.floor(Date.now()/1000);if($('#unit',c).value==='seconds')v*=1000;const d=new Date(v);$('#out1',c).innerHTML=statGrid([{label:'UTC',value:d.toUTCString()},{label:'Local',value:d.toString()}])}function calc2(){const d=new Date($('#dt',c).value);if(isNaN(d))return;$('#out2',c).innerHTML=statGrid([{label:'Unix seconds',value:Math.floor(d.getTime()/1000),cls:'accent'},{label:'Unix milliseconds',value:d.getTime()}])}$$('input,select',c).forEach(i=>i.oninput=()=>{calc1();calc2()});calc1();}
tool('timestamp-converter','Unix timestamp converter — epoch time converter online','Developer',false,'Convert Unix timestamps to human-readable dates and vice versa. Shows UTC and local time. Auto-updates with current timestamp. Free online epoch converter.','ti-clock-hour-4',renderTimestamp,{subcategory:'Time'});
function hexToRgb(hex){hex=String(hex||'').trim().replace('#','');if(hex.length===3)hex=hex.split('').map(x=>x+x).join('');if(!/^[0-9a-fA-F]{6}$/.test(hex))return null;const n=parseInt(hex,16);return{r:n>>16&255,g:n>>8&255,b:n&255}}
function rgbToHex(r,g,b){return'#'+[r,g,b].map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('')}
function rgbToHsl(r,g,b){r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b);let h,s,l=(max+min)/2;if(max===min)h=s=0;else{const d=max-min;s=l>.5?d/(2-max-min):d/(max+min);switch(max){case r:h=(g-b)/d+(g<b?6:0);break;case g:h=(b-r)/d+2;break;default:h=(r-g)/d+4}h*=60}return{h:Math.round(h),s:Math.round(s*100),l:Math.round(l*100)}}
function hslToRgb(h,s,l){h=((+h%360)+360)%360;s=Math.max(0,Math.min(100,+s))/100;l=Math.max(0,Math.min(100,+l))/100;const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;let r=0,g=0,b=0;if(h<60){r=c;g=x}else if(h<120){r=x;g=c}else if(h<180){g=c;b=x}else if(h<240){g=x;b=c}else if(h<300){r=x;b=c}else{r=c;b=x}return{r:Math.round((r+m)*255),g:Math.round((g+m)*255),b:Math.round((b+m)*255)}}
function renderColor(c){c.innerHTML='<div class="field-grid-2"><div class="field"><label>Color picker</label><input id="pick" type="color" value="#2563eb"></div><div class="field"><label>HEX</label><input id="hex" value="#2563eb" spellcheck="false"></div></div><div class="field-grid-3" style="margin-top:12px"><div class="field"><label>R</label><input id="r" type="number" min="0" max="255"></div><div class="field"><label>G</label><input id="g" type="number" min="0" max="255"></div><div class="field"><label>B</label><input id="b" type="number" min="0" max="255"></div></div><div class="field-grid-3" style="margin-top:12px"><div class="field"><label>H</label><input id="h" type="number" min="0" max="360"></div><div class="field"><label>S %</label><input id="s" type="number" min="0" max="100"></div><div class="field"><label>L %</label><input id="l" type="number" min="0" max="100"></div></div><div id="sw" class="swatch" style="margin-top:12px"></div><div id="out" class="output mono" style="margin-top:12px"></div><div class="field"><label>Contrast color</label><input id="c2" type="color" value="#ffffff"></div><div id="contrast"></div>';function cleanRgb(){return{r:Math.max(0,Math.min(255,+$('#r',c).value||0)),g:Math.max(0,Math.min(255,+$('#g',c).value||0)),b:Math.max(0,Math.min(255,+$('#b',c).value||0))}}function render(rgb){const hex=rgbToHex(rgb.r,rgb.g,rgb.b),hsl=rgbToHsl(rgb.r,rgb.g,rgb.b);$('#pick',c).value=hex;$('#hex',c).value=hex;$('#r',c).value=rgb.r;$('#g',c).value=rgb.g;$('#b',c).value=rgb.b;$('#h',c).value=hsl.h;$('#s',c).value=hsl.s;$('#l',c).value=hsl.l;$('#sw',c).style.background=hex;$('#out',c).textContent=`HEX ${hex}\nRGB rgb(${rgb.r}, ${rgb.g}, ${rgb.b})\nHSL hsl(${hsl.h}, ${hsl.s}%, ${hsl.l}%)`;const other=hexToRgb($('#c2',c).value)||{r:255,g:255,b:255};function lum(x){const arr=[x.r,x.g,x.b].map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)});return .2126*arr[0]+.7152*arr[1]+.0722*arr[2]}const ratio=(Math.max(lum(rgb),lum(other))+.05)/(Math.min(lum(rgb),lum(other))+.05);$('#contrast',c).innerHTML=statGrid([{label:'WCAG contrast',value:num(ratio,2)+':1',cls:ratio>=4.5?'success':'accent'},{label:'Normal text',value:ratio>=4.5?'Pass':'Fail'}])}$('#pick',c).oninput=()=>render(hexToRgb($('#pick',c).value));$('#hex',c).oninput=()=>{const rgb=hexToRgb($('#hex',c).value);if(rgb)render(rgb)};['r','g','b'].forEach(id=>$('#'+id,c).oninput=()=>render(cleanRgb()));['h','s','l'].forEach(id=>$('#'+id,c).oninput=()=>render(hslToRgb($('#h',c).value,$('#s',c).value,$('#l',c).value)));$('#c2',c).oninput=()=>render(cleanRgb());render(hexToRgb('#2563eb'))}
tool('color-picker','Color picker — HEX to RGB to HSL converter online free','Developer',false,'Convert between HEX, RGB, HSL, and HSV color formats. Visual color picker, WCAG contrast checker, tints and shades palette. Free online color tool.','ti-palette',renderColor,{subcategory:'Color'});

function renderCssMinifier(c){let mode='Minify';c.innerHTML='<div><label class="ctrl-label">Mode</label><div id="mode"></div></div><textarea id="in" class="mono" placeholder="Paste CSS here" style="margin-top:16px;min-height:220px"></textarea><div class="btn-row"><button id="go" class="btn btn-primary">Run</button><button id="copy" class="btn btn-secondary">Copy</button><button id="clear" class="btn btn-secondary">Clear</button></div><div id="out" class="output mono" style="margin-top:16px"></div>';$('#mode',c).appendChild(pillGroup(['Minify','Beautify'],'Minify',v=>mode=v));function minify(css){return css.replace(/\/\*[\s\S]*?\*\//g,'').replace(/\s+/g,' ').replace(/\s*([{}:;,>+~])\s*/g,'$1').replace(/;}/g,'}').trim()}function beautify(css){return minify(css).replace(/\{/g,'{\n  ').replace(/;/g,';\n  ').replace(/\}/g,'\n}\n').replace(/\n\s*\n/g,'\n').trim()}$('#go',c).onclick=()=>{$('#out',c).textContent=mode==='Minify'?minify($('#in',c).value):beautify($('#in',c).value)};$('#copy',c).onclick=()=>copyText($('#out',c).textContent);$('#clear',c).onclick=()=>{$('#in',c).value='';$('#out',c).textContent=''};}
tool('css-minifier','CSS minifier and beautifier — format CSS online free','Developer',false,'Minify or beautify CSS online. Reduce CSS file size instantly. Free, no upload, runs in browser.','ti-brand-css3',renderCssMinifier,{subcategory:'CSS'});
function renderRegex(c){c.innerHTML='<div class="field-grid-2"><div class="field"><label>Regular expression</label><input id="pat" class="mono" value="\\bword\\b"></div><div class="field"><label>Flags</label><input id="flags" class="mono" value="gi"></div></div><textarea id="text" class="mono" style="margin-top:16px;min-height:180px">word Word sword\nAnother word here.</textarea><div id="out"></div>';function run(){const out=$('#out',c);out.innerHTML='';try{const re=new RegExp($('#pat',c).value,$('#flags',c).value);const text=$('#text',c).value;const matches=[...text.matchAll(re)];out.innerHTML=statGrid([{label:'Matches',value:matches.length,cls:'accent'},{label:'Pattern valid',value:'Yes',cls:'success'}])+`<div class="results"><div class="results-header"><div class="results-title">Match list</div><div class="results-summary">${matches.length}</div></div><div class="result-rows">${matches.map((m,i)=>`<div class="result-row"><div class="result-name mono">${escapeHtml(m[0])}</div><div class="result-meta"><span class="result-new num">index ${m.index}</span></div></div>`).join('')||'<div class="result-row"><div class="result-name">No matches</div></div>'}</div></div>`}catch(e){showError(out,e.message)}}$$('input,textarea',c).forEach(i=>i.addEventListener('input',debounce(run,150)));run();}
tool('regex-tester','Regex tester — test regular expressions online free','Developer',false,'Test and debug JavaScript regular expressions online with real-time matching. Free, browser-based regex tester.','ti-code-asterisk',renderRegex,{subcategory:'Code'});
function markdownToHtml(md){let html=escapeHtml(md);html=html.replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" rel="nofollow noopener">$1</a>');html=html.split(/\n{2,}/).map(block=>{if(/^<h[1-3]>/.test(block)||/^<ul>/.test(block))return block;if(/^[-*] /m.test(block)){return '<ul>'+block.split('\n').filter(Boolean).map(line=>'<li>'+line.replace(/^[-*] /,'')+'</li>').join('')+'</ul>'}return '<p>'+block.replace(/\n/g,'<br>')+'</p>'}).join('\n');return html}
function renderMarkdown(c){c.innerHTML='<textarea id="in" class="mono" style="min-height:220px" placeholder="# Heading\n\nWrite **Markdown** here."></textarea><div class="btn-row"><button id="copy" class="btn btn-secondary">Copy HTML</button></div><div class="field-grid-2" style="margin-top:16px"><div><label class="ctrl-label">Preview</label><div id="preview" class="output"></div></div><div><label class="ctrl-label">HTML</label><div id="out" class="output mono"></div></div></div>';function run(){const html=markdownToHtml($('#in',c).value);$('#preview',c).innerHTML=html;$('#out',c).textContent=html}$('#in',c).addEventListener('input',debounce(run,150));$('#copy',c).onclick=()=>copyText($('#out',c).textContent);$('#in',c).value='# Markdown preview\n\nConvert **Markdown** to HTML locally.\n\n- Fast\n- Private\n- Free';run();}
tool('markdown-to-html','Markdown to HTML converter — free online tool','Developer',false,'Convert Markdown to HTML instantly online. Preview rendered output. Free, no upload, browser-based.','ti-markdown',renderMarkdown,{subcategory:'Converter'});
function renderIp(c){c.innerHTML='<div class="calc-result"><button id="go" class="btn btn-primary"><i class="ti ti-world"></i>Find my IP</button><div id="out" style="margin-top:16px"></div><p class="tool-desc" style="margin-top:12px">This uses api.ipify.org to read your public IP address. Location and ISP are not shown because that requires a separate geolocation provider.</p></div>';async function run(){const out=$('#out',c);out.innerHTML='<div class="loading"><div class="spinner"></div>Checking...</div>';try{const r=await fetch('https://api.ipify.org?format=json');const data=await r.json();out.innerHTML=statGrid([{label:'Public IP address',value:`<span class="mono">${escapeHtml(data.ip)}</span>`,cls:'accent'}]);}catch(e){out.innerHTML='';showError(out,'Could not fetch your IP address. Check your connection or browser privacy settings.')}}$('#go',c).onclick=run;run();}
tool('ip-lookup','IP address lookup — find your public IP address free','Developer',false,'Find your public IP address instantly. Free online IP lookup tool.','ti-world',renderIp,{subcategory:'Network'});


function wordStats(text){const words=(text.toLowerCase().match(/[a-z0-9']+/g)||[]),chars=text.length,noSpaces=text.replace(/\s/g,'').length,sent=(text.match(/[.!?]+/g)||[]).length,paras=text.trim()?text.trim().split(/\n\s*\n/).length:0;const stop=new Set('the a an is are was were and or but in on at to of for with this that it he she they we i you as be do have has had'.split(' '));const freq={};words.forEach(w=>{if(!stop.has(w))freq[w]=(freq[w]||0)+1});return{words:words.length,chars,noSpaces,sent,paras,top:Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,5)}}
function renderWord(c){c.innerHTML='<textarea id="txt" placeholder="Paste text here" style="min-height:180px"></textarea><div id="out"></div>';function calc(){const s=wordStats($('#txt',c).value);$('#out',c).innerHTML=statGrid([{label:'Words',value:s.words},{label:'Characters',value:s.chars},{label:'No spaces',value:s.noSpaces},{label:'Sentences',value:s.sent},{label:'Paragraphs',value:s.paras},{label:'Reading time',value:Math.ceil(s.words/200)+' min'},{label:'Speaking time',value:Math.ceil(s.words/130)+' min'},{label:'Top words',value:s.top.map(x=>x.join('×')).join(', ')||'None'}])}$('#txt',c).oninput=debounce(calc,150);calc();}
tool('word-counter','Word counter — count words, characters, sentences free','Text',false,'Count words, characters, sentences, paragraphs, and estimate reading time. Paste your text and get instant stats including most-used words. Free online word counter.','ti-text-size',renderWord,{subcategory:'Counting'});
function toTitle(s){return s.toLowerCase().replace(/\b\w/g,m=>m.toUpperCase())}function wordsForCase(s){return s.trim().split(/[^a-zA-Z0-9]+/).filter(Boolean)}
function renderCase(c){c.innerHTML='<textarea id="in"></textarea><div class="btn-row" id="buttons"></div><textarea id="out" readonly style="margin-top:16px"></textarea><button id="copy" class="btn btn-secondary" style="margin-top:8px">Copy</button>';const map={'UPPERCASE':s=>s.toUpperCase(),'lowercase':s=>s.toLowerCase(),'Title Case':toTitle,'Sentence case':s=>s.toLowerCase().replace(/(^\s*\w|[.!?]\s*\w)/g,m=>m.toUpperCase()),camelCase:s=>wordsForCase(s).map((w,i)=>i?w[0].toUpperCase()+w.slice(1).toLowerCase():w.toLowerCase()).join(''),PascalCase:s=>wordsForCase(s).map(w=>w[0].toUpperCase()+w.slice(1).toLowerCase()).join(''),snake_case:s=>wordsForCase(s).map(w=>w.toLowerCase()).join('_'),'kebab-case':s=>wordsForCase(s).map(w=>w.toLowerCase()).join('-')};Object.keys(map).forEach(k=>{const b=document.createElement('button');b.className='btn btn-secondary btn-sm';b.textContent=k;b.onclick=()=>{$('#out',c).value=map[k]($('#in',c).value)};$('#buttons',c).appendChild(b)});$('#copy',c).onclick=()=>copyText($('#out',c).value);}
tool('text-case','Text case converter — UPPERCASE, lowercase, title case online','Text',false,'Convert text between UPPERCASE, lowercase, Title Case, Sentence case, camelCase, PascalCase, snake_case, and kebab-case. Free online text converter.','ti-letter-case',renderCase,{subcategory:'Conversion'});
function renderDiff(c){showLoading(c);injectScript(CDN.diff).then(()=>{c.innerHTML='<div class="field-grid-2"><textarea id="a" placeholder="Original"></textarea><textarea id="b" placeholder="Changed"></textarea></div><button id="go" class="btn btn-primary" style="margin-top:12px">Compare</button><div id="out" class="output mono" style="margin-top:16px"></div>';$('#go',c).onclick=()=>{const parts=Diff.diffLines($('#a',c).value,$('#b',c).value);let add=0,rem=0;$('#out',c).innerHTML=parts.map(p=>{if(p.added)add+=p.count;if(p.removed)rem+=p.count;const bg=p.added?'var(--success-bg)':p.removed?'var(--error-bg)':'transparent';return `<div style="background:${bg};padding:2px 4px">${escapeHtml(p.value)}</div>`}).join('')+`<div class="results-summary">${add} lines added, ${rem} lines removed</div>`};});}
tool('text-diff','Text diff checker — compare two texts online free','Text',false,'Compare two texts side by side and highlight differences. See added, removed, and unchanged lines clearly. Free online text diff tool, no data sent anywhere.','ti-git-diff',renderDiff,{subcategory:'Compare'});
function renderLorem(c){let unit='Paragraphs';const corpus='Lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor incididunt ut labore et dolore magna aliqua Ut enim ad minim veniam quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur Excepteur sint occaecat cupidatat non proident sunt in culpa qui officia deserunt mollit anim id est laborum'.split(' ');c.innerHTML='<div class="field"><label>Quantity</label><input id="q" type="number" value="3"></div><div><label class="ctrl-label">Unit</label><div id="unit"></div></div><label style="display:block;margin-top:12px"><input id="start" type="checkbox" checked> Start with Lorem ipsum</label><div class="btn-row"><button id="gen" class="btn btn-primary">Generate</button><button id="copy" class="btn btn-secondary">Copy</button></div><textarea id="out" style="margin-top:16px;min-height:180px"></textarea>';$('#unit',c).appendChild(pillGroup(['Paragraphs','Sentences','Words'],'Paragraphs',v=>unit=v));function sentence(n=18){let a=Array.from({length:n},()=>corpus[Math.floor(Math.random()*corpus.length)].toLowerCase()).join(' ');return a[0].toUpperCase()+a.slice(1)+'.'}function gen(){const q=+$('#q',c).value||1;let out='';if(unit==='Words')out=Array.from({length:q},(_,i)=>$('#start',c).checked&&i<2?['Lorem','ipsum'][i]:corpus[Math.floor(Math.random()*corpus.length)].toLowerCase()).join(' ');else if(unit==='Sentences')out=Array.from({length:q},(_,i)=>i===0&&$('#start',c).checked?'Lorem ipsum dolor sit amet, consectetur adipiscing elit.':sentence()).join(' ');else out=Array.from({length:q},(_,i)=>i===0&&$('#start',c).checked?'Lorem ipsum dolor sit amet, consectetur adipiscing elit. '+sentence(16)+' '+sentence(14):sentence(18)+' '+sentence(16)+' '+sentence(14)).join('\n\n');$('#out',c).value=out}$('#gen',c).onclick=gen;$('#copy',c).onclick=()=>copyText($('#out',c).value);gen();}
tool('lorem-ipsum','Lorem ipsum generator — generate placeholder text free','Text',false,'Generate Lorem Ipsum placeholder text in paragraphs, sentences, or words. Classic or random. Copy instantly. Free online Lorem Ipsum generator.','ti-text-wrap',renderLorem,{subcategory:'Generator'});
function renderPassStrength(c){c.innerHTML='<div class="field"><label>Password</label><input id="p" type="password"></div><button id="show" class="btn btn-secondary btn-sm" style="margin-top:8px">Show / hide</button><div id="out"></div><ul id="suggest"></ul>';function calc(){const p=$('#p',c).value;let score=0,s=[];if(p.length>=8)score++;else s.push('Use at least 8 characters.');if(p.length>=12)score++;else s.push('Use at least 12 characters.');if(p.length>=16)score++;if(/[a-z]/.test(p))score++;else s.push('Add lowercase letters.');if(/[A-Z]/.test(p))score++;else s.push('Add uppercase letters.');if(/\d/.test(p))score++;else s.push('Add numbers.');if(/[^a-zA-Z0-9]/.test(p))score++;else s.push('Add symbols like !, @, #.');if(/(.)\1\1/.test(p))score--;if(/123|abc|password/i.test(p))score--;score=Math.max(0,Math.min(5,score));const labels=['Very Weak','Weak','Fair','Good','Strong','Very Strong'];$('#out',c).innerHTML=`<div class="calc-result"><div class="calc-stat-label">Strength</div><div class="bar"><div class="bar-fill ${score>=4?'success':score>=2?'warning':'error'}" style="width:${score*20}%"></div></div><div class="calc-stat-value ${score>=4?'success':'accent'}" style="margin-top:8px">${labels[score]}</div></div>`;$('#suggest',c).innerHTML=s.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}$('#p',c).oninput=calc;$('#show',c).onclick=()=>{$('#p',c).type=$('#p',c).type==='password'?'text':'password'};calc();}
tool('password-strength','Password strength checker — how strong is my password?','Text',false,'Check how strong your password is and get specific improvement suggestions. No password is stored or sent — runs 100% in your browser. Free.','ti-shield-check',renderPassStrength,{subcategory:'Security'});
function renderChar(c){let limit=280;c.innerHTML='<div><label class="ctrl-label">Platform</label><div id="platform"></div></div><input id="custom" type="number" hidden style="margin-top:8px" value="280"><textarea id="txt" style="margin-top:16px;min-height:180px"></textarea><div id="out"></div>';const opts={'Twitter/X':280,'Instagram caption':2200,'YouTube title':100,'Meta description':160,'LinkedIn post':3000,SMS:160,WhatsApp:65536,Custom:280};$('#platform',c).appendChild(pillGroup(Object.keys(opts),'Twitter/X',v=>{if(v==='Custom'){$('#custom',c).hidden=false;limit=+$('#custom',c).value}else{$('#custom',c).hidden=true;limit=opts[v]}calc()}));$('#custom',c).oninput=e=>{limit=+e.target.value||1;calc()};function calc(){const n=$('#txt',c).value.length,p=n/limit;$('#out',c).innerHTML=`<div class="calc-result"><div class="calc-stat-label">Characters</div><div class="calc-stat-value ${p>1?'accent':''}">${n} / ${limit}</div><div class="bar"><div class="bar-fill ${p>.99?'error':p>.8?'warning':'success'}" style="width:${Math.min(100,p*100)}%"></div></div></div>`}$('#txt',c).oninput=calc;calc();}
tool('char-counter','Character counter — count characters for Twitter, Instagram','Text',false,'Count characters with platform-specific limits. Twitter: 280. Instagram caption: 2,200. YouTube title: 100. LinkedIn post: 3,000. Meta description: 160. Free.','ti-keyboard',renderChar,{subcategory:'Counting'});
function renderWhatsApp(c){showLoading(c);injectScript(CDN.qr).then(()=>{c.innerHTML='<div class="field-grid-2"><div class="field"><label>Country code</label><input id="cc" value="91"></div><div class="field"><label>Phone number</label><input id="ph"></div></div><div class="field"><label>Message optional</label><textarea id="msg"></textarea></div><div id="out" class="calc-result"></div>';function calc(){const link=`https://wa.me/${$('#cc',c).value.replace(/\D/g,'')}${$('#ph',c).value.replace(/\D/g,'')}?text=${encodeURIComponent($('#msg',c).value)}`;$('#out',c).innerHTML=`<div class="output mono">${escapeHtml(link)}</div><div id="qr" style="display:flex;justify-content:center;margin-top:12px"></div><button class="btn btn-secondary" style="margin-top:12px">Copy link</button>`;makeQr($('#qr',c),link,180);$('button',$('#out',c)).onclick=()=>copyText(link)}$$('input,textarea',c).forEach(i=>i.oninput=debounce(calc,300));calc();});}
tool('whatsapp-link','WhatsApp link generator — click to chat link maker free','QR',true,'Generate a WhatsApp click-to-chat link with pre-filled message. No phone number saved in WhatsApp contacts. Share on websites or social media. Free.','ti-brand-whatsapp',renderWhatsApp,{subcategory:'Links'});
const ones=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];function below1000(n){let s='';if(n>=100){s+=ones[Math.floor(n/100)]+' Hundred ';n%=100}if(n>=20){s+=tens[Math.floor(n/10)]+' ';n%=10}if(n>0)s+=ones[n]+' ';return s.trim()}function indianWords(n){n=Math.floor(+n||0);if(n===0)return 'Zero';const parts=[[10000000,'Crore'],[100000,'Lakh'],[1000,'Thousand'],[1,'']];let s='';for(const [v,name] of parts){const q=Math.floor(n/v);if(q){s+=below1000(q)+' '+name+' ';n%=v}}return s.trim().replace(/\s+/g,' ')}
function intlWords(n){return new Intl.NumberFormat('en-IN').format(n)}
function renderWords(c){c.innerHTML='<div class="field"><label>Number</label><input id="n" type="number" value="2530000"></div><div id="out"></div>';function calc(){const n=+$('#n',c).value||0;$('#out',c).innerHTML=statGrid([{label:'Indian cheque format',value:'Rupees '+indianWords(n)+' Only',cls:'accent'},{label:'Indian numeric format',value:intlWords(n)}])}$('#n',c).oninput=calc;calc();}
tool('number-to-words','Number to words — rupees in words for cheque India','Converters',true,'Convert numbers to words in Indian format. Rupees in words for cheques and invoices. Supports lakhs and crores up to ₹99,99,99,99,999. Free.','ti-number',renderWords,{subcategory:'India'});
function gcd(a,b){return b?gcd(b,a%b):Math.abs(a)}
function renderAspect(c){c.innerHTML='<div class="field-grid-2"><div class="field"><label>Width</label><input id="w" type="number" value="1920"></div><div class="field"><label>Height</label><input id="h" type="number" value="1080"></div></div><div class="field-grid-3" style="margin-top:12px"><div class="field"><label>Ratio W</label><input id="rw" type="number" value="16"></div><div class="field"><label>Ratio H</label><input id="rh" type="number" value="9"></div><div class="field"><label>Known dimension</label><input id="known" type="number" value="1080"></div></div><div><label class="ctrl-label">Presets</label><div id="presets"></div></div><div id="out"></div>';$('#presets',c).appendChild(pillGroup(['16:9','4:3','1:1','9:16','2.35:1','3:2'],'16:9',v=>{const [a,b]=v.split(':').map(Number);$('#rw',c).value=a;$('#rh',c).value=b;calc()}));function calc(){const w=+$('#w',c).value||0,h=+$('#h',c).value||0,g=gcd(w,h)||1,rw=+$('#rw',c).value||1,rh=+$('#rh',c).value||1,k=+$('#known',c).value||0;$('#out',c).innerHTML=statGrid([{label:'Simplified ratio',value:`${w/g}:${h/g}`,cls:'accent'},{label:'Width from height',value:Math.round(k*rw/rh)+' px'},{label:'Height from width',value:Math.round(k*rh/rw)+' px'}])}$$('input',c).forEach(i=>i.oninput=calc);calc();}
